def gate_legal_module_closed() -> Dict[str, Any]:
    """G154 (v10.179) — locks Phase 4 Legal module completeness.

    The Legal module spans 10 standards (ENH-221..ENH-230). All 10
    must be status='active' for this gate to pass. Closure protection
    — once locked, regression to 'planned' or deletion of any Legal
    engine fails this gate.

    Verification: all 10 active + each named affected_engine file
    exists in utils/. ENH-221 (Contracts Lifecycle) is META_ONLY at
    closure — it has no dedicated engine and surfaces via
    legal_dashboard risk heatmap as MEDIUM until it is engineered —
    so its affected_engines tuple is empty and no file check runs.

    Mirrors G150 (Treasury module closed) and G152 (Compliance module
    closed). Twelfth module closure in platform history.

    The 10 Legal standards:
        ENH-221 → contracts (META_ONLY at closure)
        ENH-222 → obligation_tracking
        ENH-223 → legal_case_management
        ENH-224 → outside_counsel_portal
        ENH-225 → legal_spend_management
        ENH-226 → clause_library
        ENH-227 → legal_hold_management
        ENH-228 → legal_dashboard
        ENH-229 → legal_document_management
        ENH-230 → legal_analytics
    """
    from utils.standards_registry import STANDARDS_REGISTRY
    from pathlib import Path as _G154Path

    legal_ids = [f"ENH-{n}" for n in range(221, 231)]
    by_id = {s.standard_id: s for s in STANDARDS_REGISTRY}

    legal_named_engines = {
        "obligation_tracking", "legal_case_management",
        "outside_counsel_portal", "legal_spend_management",
        "clause_library", "legal_hold_management",
        "legal_dashboard", "legal_document_management",
        "legal_analytics",
    }

    violations = []
    n_active = 0
    n_total = len(legal_ids)
    utils_dir = _G154Path("utils")

    for sid in legal_ids:
        s = by_id.get(sid)
        if s is None:
            violations.append(f"v10.179: {sid} not in registry")
            continue
        if s.status != "active":
            violations.append(
                f"v10.179: {sid} status={s.status}, expected active")
            continue
        n_active += 1
        # ENH-221 is META_ONLY — no affected_engines required
        if sid == "ENH-221":
            continue
        if not s.affected_engines:
            violations.append(
                f"v10.179: {sid} has no affected_engines")
            continue
        for eng in s.affected_engines:
            if eng in legal_named_engines:
                engine_path = utils_dir / f"{eng}.py"
                if not engine_path.exists():
                    violations.append(
                        f"v10.179: {sid} engine {eng}.py missing in utils/")

    passed = (n_active == n_total) and (not violations)
    return {
        "id": "G154",
        "name": "legal_module_closed",
        "passed": passed,
        "summary": (
            f"v10.179 Legal module closure: "
            f"{n_active}/{n_total} standards active "
            f"({(n_active/n_total*100):.1f}%); "
            f"{len(violations)} violations"
            if not passed
            else f"v10.179 Legal module closure: "
                  f"{n_active}/{n_total} standards active (100%) — PASS"),
        "violations": violations,
        "n_active": n_active,
        "n_total": n_total,
    }


