def gate_partnerships_registered() -> Dict[str, Any]:
    """G166 (v10.273): Phase 2A Partnerships cluster.

    Locks 7 engine modules + cluster invariants byte-for-byte:

    1. Module imports: partner_master, contract_management,
       partner_scorecard, partner_leads_commissions,
       partner_portal_and_analytics, partner_onboarding,
       partner_risk_and_kpis
    2. PARTNER_TYPES (5) + PARTNER_STATES (6) + RISK_TIERS (4)
    3. ALLOWED_PARTNER_TRANSITIONS Rule 4 with terminals
       (OFF_BOARDED is empty)
    4. CONTRACT_TYPES (6) + CONTRACT_STATES (7) + Rule 4 terminals
       (RENEWED, EXPIRED, TERMINATED all empty)
    5. SCORECARD_DIMENSIONS (5) + DIMENSION_WEIGHTS sum=100
    6. PARTNER_TIERS (PLATINUM/GOLD/SILVER/BRONZE/AT_RISK)
    7. LEAD_STATES (7) + ALLOWED_LEAD_TRANSITIONS Rule 4 terminals
       (WON, LOST, DUPLICATE, EXPIRED all empty)
    8. Commission split bounds [MIN=0, MAX=50]
    9. ONBOARDING_GATES sequence (6 gates in order)
    10. PORTAL permission matrix: OTHER_PARTNER_DATA fully DENY,
        TRAINING_RESOURCES read=ALL
    11. RISK_DIMENSIONS (4) + RISK_DIMENSION_WEIGHTS sum=100
    12. Standards #369-#378 status="active" with implementation_batch="v10.273"
    """
    violations: List[str] = []

    required_modules = (
        "partner_master", "contract_management",
        "partner_scorecard", "partner_leads_commissions",
        "partner_portal_and_analytics", "partner_onboarding",
        "partner_risk_and_kpis",
    )
    imported: Dict[str, Any] = {}
    for mod_name in required_modules:
        try:
            mod = __import__(f"utils.{mod_name}", fromlist=[mod_name])
            imported[mod_name] = mod
        except ImportError as e:
            violations.append(f"module_import_failed:{mod_name}:{type(e).__name__}")

    if violations:
        return {
            "id": "G166",
            "name": "partnerships_registered",
            "passed": False,
            "violations": violations,
            "summary": f"v10.273 Partnerships: {len(violations)} module import failures",
        }

    from decimal import Decimal as _D

    # 2. Partner types/states/risk tiers
    pm = imported["partner_master"]
    if pm.PARTNER_TYPES != ("REFERRAL", "INTEGRATION", "DISTRIBUTION",
                              "ECOSYSTEM", "SERVICE"):
        violations.append(f"partner_types_drift:{pm.PARTNER_TYPES}")
    if pm.PARTNER_STATES != ("PROSPECT", "ONBOARDING", "ACTIVE",
                                "SUSPENDED", "OFF_BOARDING", "OFF_BOARDED"):
        violations.append(f"partner_states_drift:{pm.PARTNER_STATES}")
    if pm.RISK_TIERS != ("LOW", "MEDIUM", "HIGH", "CRITICAL"):
        violations.append(f"risk_tiers_drift:{pm.RISK_TIERS}")

    # 3. Partner state machine — OFF_BOARDED terminal
    if pm.ALLOWED_PARTNER_TRANSITIONS.get("OFF_BOARDED") != ():
        violations.append(
            f"off_boarded_not_terminal:"
            f"{pm.ALLOWED_PARTNER_TRANSITIONS.get('OFF_BOARDED')}"
        )

    # 4. Contract types/states + terminals
    cm = imported["contract_management"]
    if cm.CONTRACT_TYPES != ("MOU", "SLA", "REFERRAL", "DISTRIBUTION",
                                "INTEGRATION", "NDA"):
        violations.append(f"contract_types_drift:{cm.CONTRACT_TYPES}")
    expected_contract_states = ("DRAFT", "UNDER_REVIEW", "SIGNED",
                                  "AMENDED", "RENEWED", "EXPIRED", "TERMINATED")
    if cm.CONTRACT_STATES != expected_contract_states:
        violations.append(f"contract_states_drift:{cm.CONTRACT_STATES}")
    for terminal in ("RENEWED", "EXPIRED", "TERMINATED"):
        if cm.ALLOWED_CONTRACT_TRANSITIONS.get(terminal) != ():
            violations.append(f"contract_terminal_violation:{terminal}")

    # 5. Scorecard dimensions + weight sum
    sc = imported["partner_scorecard"]
    if sc.SCORECARD_DIMENSIONS != ("REVENUE_KES", "LEADS_DELIVERED",
                                       "CONVERSION_RATE", "CSAT_SCORE",
                                       "COMPLIANCE_SCORE"):
        violations.append(f"scorecard_dimensions_drift:{sc.SCORECARD_DIMENSIONS}")
    if sum(sc.DIMENSION_WEIGHTS.values()) != _D("100"):
        violations.append(
            f"scorecard_weights_sum_drift:{sum(sc.DIMENSION_WEIGHTS.values())}"
        )

    # 6. Partner tiers
    if sc.PARTNER_TIERS != ("PLATINUM", "GOLD", "SILVER", "BRONZE", "AT_RISK"):
        violations.append(f"partner_tiers_drift:{sc.PARTNER_TIERS}")

    # 7. Lead states + terminals
    lc = imported["partner_leads_commissions"]
    if lc.LEAD_STATES != ("NEW", "QUALIFIED", "IN_PIPELINE",
                              "WON", "LOST", "DUPLICATE", "EXPIRED"):
        violations.append(f"lead_states_drift:{lc.LEAD_STATES}")
    for terminal in ("WON", "LOST", "DUPLICATE", "EXPIRED"):
        if lc.ALLOWED_LEAD_TRANSITIONS.get(terminal) != ():
            violations.append(f"lead_terminal_violation:{terminal}")

    # 8. Commission split bounds
    if lc.MIN_COMMISSION_SPLIT_PCT != _D("0"):
        violations.append(f"min_commission_drift:{lc.MIN_COMMISSION_SPLIT_PCT}")
    if lc.MAX_COMMISSION_SPLIT_PCT != _D("50"):
        violations.append(f"max_commission_drift:{lc.MAX_COMMISSION_SPLIT_PCT}")

    # 9. Onboarding gate sequence
    ob = imported["partner_onboarding"]
    expected_gates = ("DUE_DILIGENCE", "CONTRACT", "TRAINING",
                        "SYSTEM_ACCESS", "SANDBOX_TESTING", "GO_LIVE_APPROVAL")
    if ob.ONBOARDING_GATES != expected_gates:
        violations.append(f"onboarding_gates_drift:{ob.ONBOARDING_GATES}")

    # 10. Portal permission matrix
    pa = imported["partner_portal_and_analytics"]
    other_partner = pa.PORTAL_PERMISSION_MATRIX.get("OTHER_PARTNER_DATA", {})
    if other_partner.get("read") != "DENY" or other_partner.get("write") != "DENY":
        violations.append("other_partner_data_not_fully_denied")
    training = pa.PORTAL_PERMISSION_MATRIX.get("TRAINING_RESOURCES", {})
    if training.get("read") != "ALL":
        violations.append(f"training_read_drift:{training.get('read')}")
    if pa.PORTAL_ROLE_NAME != "PARTNER_PORTAL_USER":
        violations.append(f"portal_role_name_drift:{pa.PORTAL_ROLE_NAME}")

    # 11. Risk dimensions + weight sum
    rk = imported["partner_risk_and_kpis"]
    if rk.RISK_DIMENSIONS != ("FINANCIAL_HEALTH", "REGULATORY_STANDING",
                                 "CYBER_POSTURE", "CUSTOMER_COMPLAINTS"):
        violations.append(f"risk_dimensions_drift:{rk.RISK_DIMENSIONS}")
    if sum(rk.RISK_DIMENSION_WEIGHTS.values()) != _D("100"):
        violations.append(
            f"risk_weights_sum_drift:{sum(rk.RISK_DIMENSION_WEIGHTS.values())}"
        )

    # 12. Standards registry
    try:
        from utils import standards_registry as sr
        partnerships = sr.PARTNERSHIPS_ENHANCEMENT_STANDARDS
        if len(partnerships) != 10:
            violations.append(f"standards_count_drift:{len(partnerships)}")
        for s in partnerships:
            if s.status != "active":
                violations.append(f"standard_not_active:{s.standard_id}:{s.status}")
            if s.implementation_batch != "v10.273":
                violations.append(
                    f"standard_batch_drift:{s.standard_id}:{s.implementation_batch}"
                )
    except (ImportError, AttributeError) as e:
        violations.append(f"standards_registry_lookup_failed:{type(e).__name__}")

    return {
        "id": "G166",
        "name": "partnerships_registered",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            "v10.273 Phase 2A Partnerships: 7 engines registered; "
            "PARTNER_TYPES (5) + PARTNER_STATES (6) + RISK_TIERS (4) "
            "byte-for-byte; partner + contract + lead state machines "
            "Rule 4 with terminals locked; commission split bounds "
            "[0,50]; portal cross-partner isolation locked; risk "
            "dimensions weights sum=100 "
            f"({len(violations)} violations)"
        ),
    }


def gate_bancassurance_registered() -> Dict[str, Any]:
    """G167 (v10.274): Phase 2A Bancassurance cluster.

    Locks 7 engine modules + cluster invariants byte-for-byte:

    1. Module imports (7): insurance_catalog, insurance_recommendation,
       insurance_partner_hub, insurance_claims, insurance_commission_recon,
       insurance_customer_rm_desktop, insurance_ira_compliance
    2. INSURANCE_PRODUCT_TYPES (10): LIFE/HEALTH/MOTOR/PROPERTY/TRAVEL/
       PERSONAL_ACCIDENT/EDUCATION/PENSION/BUSINESS/MARINE
    3. POLICY_STATES (9) with EXPIRED/CANCELLED/SURRENDERED terminals
    4. PREMIUM_FREQUENCIES (5) + DEFAULT_GRACE_PERIOD_DAYS=30
    5. LIFE_EVENTS (10) byte-for-byte + SCORING_WEIGHTS sum=100
       + SPEC_DEVIATION_NOTE present (Rule 7 ML hook)
    6. INSURER_STATES (7) with OFF_BOARDED terminal + QUOTE_STATES (5)
       + DEFAULT_QUOTE_VALIDITY_DAYS=30
    7. CLAIM_STATES (8) with CLOSED terminal + REQUIRED_DOCUMENT_TYPES
       map + AUTO_APPROVAL_THRESHOLD_KES=100000 +
       AUTO_APPROVAL_FRAUD_LIMIT=40 + SPEC_DEVIATION_NOTE present
    8. RECON_STATES (6) + DISPUTE_STATES (6) +
       RECONCILIATION_TOLERANCE_PCT=1
    9. INSURER_SCORECARD_DIMENSIONS (6) + INSURER_DIMENSION_WEIGHTS
       sum=100 + INSURER_TIERS (PREFERRED/PARTNER/OBSERVATION/AT_RISK)
    10. EXPECTED_COVERAGE_BASELINES + RM_KPI_DIMENSIONS (6)
    11. LICENSE_STATES (5) with EXPIRED/REVOKED terminals
        + IRA_RETURN_TYPES (5) byte-for-byte
        + DEFAULT_LICENSE_EXPIRY_WARNING_DAYS=30
    12. Standards #301-#310 status="active" with implementation_batch="v10.274"
    """
    violations: List[str] = []

    required_modules = (
        "insurance_catalog", "insurance_recommendation",
        "insurance_partner_hub", "insurance_claims",
        "insurance_commission_recon", "insurance_customer_rm_desktop",
        "insurance_ira_compliance",
    )
    imported: Dict[str, Any] = {}
    for mod_name in required_modules:
        try:
            mod = __import__(f"utils.{mod_name}", fromlist=[mod_name])
            imported[mod_name] = mod
        except ImportError as e:
            violations.append(f"module_import_failed:{mod_name}:{type(e).__name__}")

    if violations:
        return {
            "id": "G167",
            "name": "bancassurance_registered",
            "passed": False,
            "violations": violations,
            "summary": f"v10.274 Bancassurance: {len(violations)} module import failures",
        }

    from decimal import Decimal as _D

    # 2. Insurance product types
    cat = imported["insurance_catalog"]
    expected_types = ("LIFE", "HEALTH", "MOTOR", "PROPERTY", "TRAVEL",
                        "PERSONAL_ACCIDENT", "EDUCATION", "PENSION",
                        "BUSINESS", "MARINE")
    if cat.INSURANCE_PRODUCT_TYPES != expected_types:
        violations.append(f"insurance_product_types_drift:{cat.INSURANCE_PRODUCT_TYPES}")

    # 3. Policy states + terminals
    expected_policy_states = ("QUOTED", "APPLIED", "UNDERWRITING", "ACTIVE",
                                  "LAPSED", "SUSPENDED", "EXPIRED", "CANCELLED",
                                  "SURRENDERED")
    if cat.POLICY_STATES != expected_policy_states:
        violations.append(f"policy_states_drift:{cat.POLICY_STATES}")
    for terminal in ("EXPIRED", "CANCELLED", "SURRENDERED"):
        if cat.ALLOWED_POLICY_TRANSITIONS.get(terminal) != ():
            violations.append(f"policy_terminal_violation:{terminal}")

    # 4. Premium frequencies + grace period
    if cat.PREMIUM_FREQUENCIES != ("SINGLE", "MONTHLY", "QUARTERLY",
                                       "SEMI_ANNUAL", "ANNUAL"):
        violations.append(f"premium_frequencies_drift:{cat.PREMIUM_FREQUENCIES}")
    if cat.DEFAULT_GRACE_PERIOD_DAYS != 30:
        violations.append(
            f"default_grace_period_drift:{cat.DEFAULT_GRACE_PERIOD_DAYS}"
        )

    # 5. Recommendation engine + Rule 7
    rec = imported["insurance_recommendation"]
    expected_life_events = ("NEW_CUSTOMER", "MARRIAGE", "NEW_CHILD",
                                "HOUSE_PURCHASE", "VEHICLE_PURCHASE",
                                "BUSINESS_OPENING", "JOB_CHANGE",
                                "NEAR_RETIREMENT", "INCOME_INCREASE",
                                "POLICY_LAPSE")
    if rec.LIFE_EVENTS != expected_life_events:
        violations.append(f"life_events_drift:{rec.LIFE_EVENTS}")
    if sum(rec.SCORING_WEIGHTS.values()) != _D("100"):
        violations.append(
            f"recommendation_weights_sum_drift:{sum(rec.SCORING_WEIGHTS.values())}"
        )
    if not getattr(rec, "SPEC_DEVIATION_NOTE", ""):
        violations.append("recommendation_missing_spec_deviation_note")

    # 6. Partner hub
    hub = imported["insurance_partner_hub"]
    expected_insurer_states = ("DISCOVERY", "NEGOTIATING", "INTEGRATING",
                                   "INTEGRATED", "SUSPENDED", "OFF_BOARDING",
                                   "OFF_BOARDED")
    if hub.INSURER_STATES != expected_insurer_states:
        violations.append(f"insurer_states_drift:{hub.INSURER_STATES}")
    if hub.ALLOWED_INSURER_TRANSITIONS.get("OFF_BOARDED") != ():
        violations.append("insurer_off_boarded_not_terminal")
    if hub.QUOTE_STATES != ("REQUESTED", "QUOTED", "EXPIRED",
                                "CONVERTED", "CANCELLED"):
        violations.append(f"quote_states_drift:{hub.QUOTE_STATES}")
    if hub.DEFAULT_QUOTE_VALIDITY_DAYS != 30:
        violations.append(
            f"quote_validity_drift:{hub.DEFAULT_QUOTE_VALIDITY_DAYS}"
        )

    # 7. Claims engine
    cl = imported["insurance_claims"]
    expected_claim_states = ("SUBMITTED", "DOCUMENT_REVIEW", "INVESTIGATING",
                                 "APPROVED", "REJECTED", "SETTLED",
                                 "CONTESTED", "CLOSED")
    if cl.CLAIM_STATES != expected_claim_states:
        violations.append(f"claim_states_drift:{cl.CLAIM_STATES}")
    if cl.ALLOWED_CLAIM_TRANSITIONS.get("CLOSED") != ():
        violations.append("claim_closed_not_terminal")
    # REQUIRED_DOCUMENT_TYPES
    expected_doc_keys = {"LIFE", "HEALTH", "MOTOR", "PROPERTY", "TRAVEL", "OTHER"}
    if set(cl.REQUIRED_DOCUMENT_TYPES.keys()) != expected_doc_keys:
        violations.append(
            f"required_doc_types_keys_drift:{sorted(cl.REQUIRED_DOCUMENT_TYPES.keys())}"
        )
    # Critical doc requirements
    if "DEATH_CERTIFICATE" not in cl.REQUIRED_DOCUMENT_TYPES.get("LIFE", ()):
        violations.append("life_missing_death_certificate")
    if "POLICE_ABSTRACT" not in cl.REQUIRED_DOCUMENT_TYPES.get("MOTOR", ()):
        violations.append("motor_missing_police_abstract")
    if cl.AUTO_APPROVAL_THRESHOLD_KES != _D("100000"):
        violations.append(
            f"auto_approval_threshold_drift:{cl.AUTO_APPROVAL_THRESHOLD_KES}"
        )
    if cl.AUTO_APPROVAL_FRAUD_LIMIT != _D("40"):
        violations.append(
            f"auto_approval_fraud_limit_drift:{cl.AUTO_APPROVAL_FRAUD_LIMIT}"
        )
    if not getattr(cl, "SPEC_DEVIATION_NOTE", ""):
        violations.append("claims_missing_spec_deviation_note")

    # 8. Commission recon + dispute states
    rcn = imported["insurance_commission_recon"]
    expected_recon = ("PENDING_MATCH", "MATCHED", "PARTIALLY_MATCHED",
                         "DISPUTED", "RESOLVED", "WRITTEN_OFF")
    if rcn.RECON_STATES != expected_recon:
        violations.append(f"recon_states_drift:{rcn.RECON_STATES}")
    expected_dispute = ("OPEN", "UNDER_REVIEW", "INSURER_RESPONSE",
                            "RESOLVED_PAID", "RESOLVED_WRITTEN_OFF", "ESCALATED")
    if rcn.DISPUTE_STATES != expected_dispute:
        violations.append(f"dispute_states_drift:{rcn.DISPUTE_STATES}")
    if rcn.RECONCILIATION_TOLERANCE_PCT != _D("1"):
        violations.append(
            f"recon_tolerance_drift:{rcn.RECONCILIATION_TOLERANCE_PCT}"
        )

    # 9. Insurer scorecard
    expected_scorecard = ("POLICY_COUNT", "PREMIUM_VOLUME_KES",
                              "COMMISSION_KES", "CLAIM_RATIO",
                              "CUSTOMER_SATISFACTION", "DISPUTE_RESOLUTION_DAYS")
    if rcn.INSURER_SCORECARD_DIMENSIONS != expected_scorecard:
        violations.append(
            f"insurer_scorecard_dims_drift:{rcn.INSURER_SCORECARD_DIMENSIONS}"
        )
    if sum(rcn.INSURER_DIMENSION_WEIGHTS.values()) != _D("100"):
        violations.append(
            f"insurer_weights_sum_drift:{sum(rcn.INSURER_DIMENSION_WEIGHTS.values())}"
        )
    if rcn.INSURER_TIERS != ("PREFERRED", "PARTNER", "OBSERVATION", "AT_RISK"):
        violations.append(f"insurer_tiers_drift:{rcn.INSURER_TIERS}")

    # 10. Customer + RM desktop
    rm = imported["insurance_customer_rm_desktop"]
    expected_rm_kpis = ("POLICIES_ACTIVE", "NEW_POLICIES_PERIOD",
                            "PREMIUM_COLLECTED", "CLAIM_COUNT_OPEN",
                            "EXPIRING_SOON", "COVERAGE_GAP_LEADS")
    if rm.RM_KPI_DIMENSIONS != expected_rm_kpis:
        violations.append(f"rm_kpi_dims_drift:{rm.RM_KPI_DIMENSIONS}")
    if "adult_earner" not in rm.EXPECTED_COVERAGE_BASELINES:
        violations.append("missing_adult_earner_baseline")

    # 11. IRA compliance
    ira = imported["insurance_ira_compliance"]
    expected_license = ("ACTIVE", "EXPIRING_SOON", "EXPIRED",
                            "REVOKED", "SUSPENDED")
    if ira.LICENSE_STATES != expected_license:
        violations.append(f"license_states_drift:{ira.LICENSE_STATES}")
    if ira.ALLOWED_LICENSE_TRANSITIONS.get("EXPIRED") != ():
        violations.append("license_expired_not_terminal")
    if ira.ALLOWED_LICENSE_TRANSITIONS.get("REVOKED") != ():
        violations.append("license_revoked_not_terminal")
    expected_returns = ("PREMIUM_REMITTANCE", "CLAIM_RATIO",
                            "AGENT_REGISTER", "SOLVENCY_BUFFER",
                            "COMPOSITE_QUARTERLY")
    if ira.IRA_RETURN_TYPES != expected_returns:
        violations.append(f"ira_return_types_drift:{ira.IRA_RETURN_TYPES}")
    if ira.DEFAULT_LICENSE_EXPIRY_WARNING_DAYS != 30:
        violations.append(
            f"license_warning_days_drift:{ira.DEFAULT_LICENSE_EXPIRY_WARNING_DAYS}"
        )

    # 12. Standards registry
    try:
        from utils import standards_registry as sr
        bancass = sr.BANCASSURANCE_ENHANCEMENT_STANDARDS
        if len(bancass) != 10:
            violations.append(f"bancassurance_standards_count_drift:{len(bancass)}")
        for s in bancass:
            if s.status != "active":
                violations.append(f"standard_not_active:{s.standard_id}:{s.status}")
            if s.implementation_batch != "v10.274":
                violations.append(
                    f"standard_batch_drift:{s.standard_id}:{s.implementation_batch}"
                )
    except (ImportError, AttributeError) as e:
        violations.append(f"standards_registry_lookup_failed:{type(e).__name__}")

    return {
        "id": "G167",
        "name": "bancassurance_registered",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            "v10.274 Phase 2A Bancassurance: 7 engines registered; "
            "INSURANCE_PRODUCT_TYPES (10) byte-for-byte; POLICY_STATES "
            "(9) + CLAIM_STATES (8) + LICENSE_STATES (5) Rule 4 with "
            "terminals locked; AUTO_APPROVAL_THRESHOLD=100000; "
            "AUTO_APPROVAL_FRAUD_LIMIT=40; recon tolerance=1%; "
            "Rule 7 SPEC_DEVIATION_NOTE present on recommendation + "
            "claims engines; LIFE_EVENTS (10) + IRA_RETURN_TYPES (5) "
            f"locked ({len(violations)} violations)"
        ),
    }


