def gate_cims_live_cockpit_integrated() -> Dict[str, Any]:
    """G186 — v10.295 Phase 3 CIMS live cockpit integration lock.

    Locks the discipline that closes the G130 deferred-to-closure
    obligation for the CIMS arc:

      1. pages/109_cims_live.py exists and uses canonical imports
      2. require_access is loaded WITHOUT try/except swallow on
         pages 105, 106, 107, 108, 109 (Phase 3 standing rule:
         pages fail loud on misconfigured access)
      3. utils/cockpit_read.py exists and exposes the documented
         API: load_records, filter_records, sort_records,
         group_by, count_by, find_by_id, latest_n,
         cims_instruction_trace, cims_open_work
      4. Page 109 manifest entry exists with module_path
         "operations.cims_live"
      5. Page 109 uses @st.cache_data with TTL for read views
         (cockpit must refresh, not hold stale data forever)

    Failure modes this gate catches:
      - Someone re-introduces the silent try/except around
        require_access (the bug we removed in v10.295)
      - utils/cockpit_read.py gets deleted or refactored without
        preserving the documented API surface
      - Page 109 ships without the live-data cache wiring,
        which would make it look "live" but actually stale

    Shipped: v10.295.
    """
    import importlib as _importlib

    violations: List[str] = []

    # ---- Check 1: page 109 exists ----
    page_109 = (
        Path(__file__).parent.parent / "pages" / "109_cims_live.py"
    )
    if not page_109.exists():
        violations.append("pages/109_cims_live.py missing")
        return {
            "id": "G186",
            "name": "cims_live_cockpit_integrated",
            "passed": False,
            "violations": violations,
            "summary": "G186 page 109 missing",
        }

    page_109_src = page_109.read_text()
    # v10.345 — body moved to utils/live_cockpit_render.py;
    # extend the source we examine to include the helper module
    _render_path = Path(__file__).parent.parent / "utils" / "live_cockpit_render.py"
    if _render_path.exists():
        page_109_src = page_109_src + "\n" + _render_path.read_text()

    # ---- Check 2: no silent require_access swallow ----
    silent_pattern = (
        "try:\n"
        "    from pages._access import require_access\n"
    )
    cims_pages = [
        "105_cims_capture.py", "106_cims_process.py",
        "107_cims_compliance.py", "108_cims_closure.py",
        "109_cims_live.py",
    ]
    pages_dir = Path(__file__).parent.parent / "pages"
    for pname in cims_pages:
        p = pages_dir / pname
        if not p.exists():
            continue  # other checks catch this
        src = p.read_text()
        if silent_pattern in src:
            violations.append(
                f"{pname}: silent try/except around require_access "
                f"(Phase 3 standing rule: pages must fail loud)"
            )

    # ---- Check 3: cockpit_read exposes documented API ----
    try:
        cr = _importlib.import_module("utils.cockpit_read")
    except Exception as exc:
        violations.append(
            f"import_error utils.cockpit_read: {exc}"
        )
        return {
            "id": "G186",
            "name": "cims_live_cockpit_integrated",
            "passed": False,
            "violations": violations,
            "summary": "G186 import error",
        }

    required_api = [
        "load_records", "filter_records", "sort_records",
        "group_by", "count_by", "find_by_id", "latest_n",
        "cims_instruction_trace", "cims_open_work",
    ]
    for fn_name in required_api:
        if not hasattr(cr, fn_name):
            violations.append(
                f"utils.cockpit_read missing API: {fn_name}"
            )

    # ---- Check 4: page 109 manifest entry ----
    manifest_path = (
        Path(__file__).parent.parent / "pages" / "_manifest.json"
    )
    if manifest_path.exists():
        import json as _json
        m = _json.loads(manifest_path.read_text())
        entry = m.get("pages", {}).get("109_cims_live.py")
        if not entry:
            violations.append(
                "manifest missing 109_cims_live.py entry"
            )
        elif entry.get("module_path") != "operations.cims_live":
            violations.append(
                f"109_cims_live.py module_path != "
                f"'operations.cims_live' "
                f"(got '{entry.get('module_path')}')"
            )

    # ---- Check 5: page 109 uses TTL caching ----
    if "@st.cache_data(ttl=" not in page_109_src:
        violations.append(
            "pages/109_cims_live.py missing @st.cache_data(ttl=...) "
            "decorator — live cockpit must refresh, not cache "
            "indefinitely"
        )

    # ---- Check 6: page 109 calls audit_log ----
    if "audit_log(" not in page_109_src:
        violations.append(
            "pages/109_cims_live.py missing audit_log() call "
            "(Phase 3 standing rule: cockpits emit real audit trail)"
        )

    return {
        "id": "G186",
        "name": "cims_live_cockpit_integrated",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            "v10.295 Phase 3 CIMS live cockpit integration: "
            "pages/109_cims_live.py composes all 15 CIMS engines; "
            "utils/cockpit_read.py exposes load_records + "
            "filter_records + sort_records + group_by + count_by + "
            "find_by_id + latest_n + cims_instruction_trace + "
            "cims_open_work; pages 105/106/107/108/109 use hard "
            "require_access (no silent try/except); 7 tabs at G4 "
            "ceiling; @st.cache_data(ttl=10) for live refresh; "
            "audit_log emits real trail; G130 deferred-to-closure "
            "obligation closed for CIMS arc "
            f"({len(violations)} violations)"
        ),
    }


