def gate_cims_vocabulary_harmonized() -> Dict[str, Any]:
    """G194 — v10.303 Phase 3 CIMS vocabulary harmonization.

    Closes backlog item B-001 (logged v10.295): different CIMS
    engines used different names for the same semantic concept
    (`COMPLAINT` at capture vs `CUSTOMER_COMPLAINT` at SLA),
    breaking cross-engine joins.

    The fix is a translation layer in cockpit_read, not engine
    rewrites — engines stay byte-for-byte locked under
    G182-G185.

    Checks:
      1. utils.cockpit_read.normalize_instruction_type exists
      2. Maps `COMPLAINT` → `CUSTOMER_COMPLAINT`
      3. Maps `INFORMATION_REQUEST` → `GENERAL_INQUIRY`
      4. Idempotent (already-canonical values pass through)
      5. Unknown values pass through unchanged
      6. utils.cockpit_read.cims_vocabulary_map exists with
         capture + nlp + canonical groups
      7. Every canonical target is a real key in SLA framework's
         INSTRUCTION_TYPE_DEFAULT_DEADLINES_HOURS
      8. cims_instruction_trace enriches capture with
         canonical_instruction_type field

    Shipped: v10.303.
    """
    import importlib as _importlib

    violations: List[str] = []

    try:
        cr = _importlib.import_module("utils.cockpit_read")
    except Exception as exc:
        return {
            "id": "G194",
            "name": "cims_vocabulary_harmonized",
            "passed": False,
            "violations": [
                f"cockpit_read import error: {exc}"
            ],
            "summary": "G194 cockpit_read missing",
        }

    # Check 1
    if not hasattr(cr, "normalize_instruction_type"):
        violations.append(
            "cockpit_read missing normalize_instruction_type"
        )

    # Check 2-5: mappings
    if hasattr(cr, "normalize_instruction_type"):
        nm = cr.normalize_instruction_type
        if nm("COMPLAINT") != "CUSTOMER_COMPLAINT":
            violations.append(
                f"normalise(COMPLAINT) → "
                f"{nm('COMPLAINT')!r}; expected "
                f"'CUSTOMER_COMPLAINT'"
            )
        if nm("INFORMATION_REQUEST") != "GENERAL_INQUIRY":
            violations.append(
                f"normalise(INFORMATION_REQUEST) → "
                f"{nm('INFORMATION_REQUEST')!r}; expected "
                f"'GENERAL_INQUIRY'"
            )
        # Idempotency
        once = nm("COMPLAINT")
        twice = nm(once)
        if once != twice:
            violations.append(
                f"normalise not idempotent: {once!r} → "
                f"{twice!r}"
            )
        # Unknown passthrough
        if nm("WIDGET_FOOBAR") != "WIDGET_FOOBAR":
            violations.append(
                "normalise unknown should pass through "
                "unchanged"
            )

    # Check 6: vocabulary_map structure
    if not hasattr(cr, "cims_vocabulary_map"):
        violations.append(
            "cockpit_read missing cims_vocabulary_map"
        )
    else:
        vm = cr.cims_vocabulary_map()
        for group in ("capture", "nlp", "canonical"):
            if group not in vm:
                violations.append(
                    f"vocabulary_map missing `{group}` group"
                )

    # Check 7: canonical targets exist in SLA framework
    try:
        sla_mod = _importlib.import_module(
            "utils.cims_regulatory_sla")
        sla_keys = set(
            sla_mod.INSTRUCTION_TYPE_DEFAULT_DEADLINES_HOURS
        )
        if hasattr(cr, "cims_vocabulary_map"):
            vm = cr.cims_vocabulary_map()
            for group_name in ("capture", "nlp"):
                for raw, canonical in vm.get(
                    group_name, {}).items():
                    if canonical not in sla_keys:
                        violations.append(
                            f"vocabulary_map[{group_name}]"
                            f"[{raw!r}] = {canonical!r} not in "
                            f"SLA INSTRUCTION_TYPE_DEFAULT_"
                            f"DEADLINES_HOURS keys "
                            f"{sorted(sla_keys)}"
                        )
    except Exception as exc:
        violations.append(
            f"SLA module check failed: {exc}"
        )

    # Check 8: trace enrichment (greppable)
    try:
        cr_src = Path(cr.__file__).read_text()
        if "canonical_instruction_type" not in cr_src:
            violations.append(
                "cockpit_read source missing "
                "canonical_instruction_type enrichment in "
                "cims_instruction_trace"
            )
    except Exception:
        pass

    return {
        "id": "G194",
        "name": "cims_vocabulary_harmonized",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            "v10.303 Phase 3 CIMS vocabulary harmonisation "
            "(B-001 closure): "
            "utils.cockpit_read.normalize_instruction_type "
            "translates capture/NLP vocabularies (COMPLAINT, "
            "INFORMATION_REQUEST) to canonical SLA framework "
            "keys (CUSTOMER_COMPLAINT, GENERAL_INQUIRY); "
            "cims_vocabulary_map exposes the full mapping "
            "table for operators + React SPA; "
            "cims_instruction_trace enriches each capture "
            "record with canonical_instruction_type so "
            "downstream consumers can join against SLA "
            "deadlines without re-implementing the mapping "
            f"({len(violations)} violations)"
        ),
    }


