def gate_static_function_checks() -> Dict[str, Any]:
    """G238 — v10.352 Static AST checks across utils/ + pages/.

    Catches two bug classes that pure module-load smoke can't detect:
      CLASS 1 (undefined_caps_constant): ALL_CAPS names used inside a
        function body that are not bound through own scope, enclosing
        scopes, class body, module top, or builtins. The v10.350
        STREAMLIT_AVAILABLE pattern.
      CLASS 2 (unbound_local_import): local imports inside a function
        that shadow a module-top import AND have a USE of the same name
        BEFORE the earliest local binding line — Python's
        UnboundLocalError trap. The v10.351 get_stock_snapshot pattern.

    Both classes are real bugs (latent NameError / UnboundLocalError that
    only fires when the specific code path runs). The static AST analyzer
    catches them deterministically at zero runtime cost — the smoke test
    cannot, because it only checks module-load integrity.

    Shipped: v10.352.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    try:
        import sys
        if str(repo) not in sys.path:
            sys.path.insert(0, str(repo))
        from utils.static_check import static_check_paths
    except Exception as exc:
        return {
            "id": "G238",
            "name": "static_function_checks",
            "passed": False,
            "violations": [f"utils.static_check unavailable: {exc}"],
            "summary": "G238 setup failed",
        }

    paths = sorted((repo / "utils").glob("*.py")) + sorted(
        (repo / "pages").glob("[0-9]*.py")
    )
    findings = static_check_paths(paths)

    for f in findings:
        rel = f.file.replace(str(repo) + "/", "")
        violations.append(
            f"{rel}:{f.line} in {f.function}() — {f.category}: {f.name}"
        )

    return {
        "id": "G238",
        "name": "static_function_checks",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            "v10.352 Static AST checks across all utils/*.py and "
            "pages/[0-9]*.py. Catches undefined ALL_CAPS constants used "
            "inside function bodies (v10.350 STREAMLIT_AVAILABLE class) "
            "and shadowing local imports that produce UnboundLocalError "
            "(v10.351 get_stock_snapshot class). Both are real bugs that "
            "the module-load smoke test cannot detect because they fire "
            "only when specific code paths execute. The AST analyzer "
            "catches them deterministically without needing to execute "
            f"render functions. {len(violations)} violations"
        ),
    }


def gate_dynamic_render_smoke() -> Dict[str, Any]:
    """G239 — v10.353 Dynamic render-function smoke.

    Calls every render function in the dynamic_smoke RENDER_REGISTRY
    with a synthetic actor and reports which succeed. Effective pass
    rate excludes intentional `st.stop()` access gating and documented
    skip exemptions (renders that spawn subprocesses for live
    diagnostics, etc.).

    Failure threshold: any render in the "effective" set (not stopped,
    not skipped) that crashes triggers a violation. Failures are
    classified by category — REAL_BUG, MOCK_GAP, DATA_MISSING — for
    triage.

    This catches the bug classes that module-load smoke (G231) and
    static AST checks (G238) cannot:
      - KeyError on data fields not present
      - TypeError on operations inside render logic
      - AttributeError on dynamic attribute access
      - Use-after-free / state errors that only fire at render time

    Shipped: v10.353.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    try:
        import sys
        if str(repo) not in sys.path:
            sys.path.insert(0, str(repo))
        from utils.dynamic_smoke import smoke_test_renders
    except Exception as exc:
        return {
            "id": "G239",
            "name": "dynamic_render_smoke",
            "passed": False,
            "violations": [f"utils.dynamic_smoke unavailable: {exc}"],
            "summary": "G239 setup failed",
        }

    report = smoke_test_renders()

    for failure in report["failures"]:
        violations.append(
            f"{failure['function']} [{failure['category'] or failure['status']}]: "
            f"{(failure['error'] or '')[:120]}"
        )

    return {
        "id": "G239",
        "name": "dynamic_render_smoke",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            "v10.353 Dynamic render-function smoke. Calls every render in "
            "the registry with a synthetic actor and reports per-render "
            "status. Catches runtime errors that module-load smoke (G231) "
            "and static AST checks (G238) cannot — KeyError on missing "
            "data fields, TypeError on operations, AttributeError on "
            "dynamic attribute access, use-before-state errors. "
            f"{report['passed']}/{report['effective_total']} effective "
            f"renders pass ({report['effective_pass_rate']:.1%}). "
            f"Intentional access gating: {report['stopped']}. Documented "
            f"skips: {report['skipped']}. {len(violations)} violations"
        ),
    }


def gate_cbs_baseline() -> Dict[str, Any]:
    """G240 — v10.354 CBS baseline snapshot present + valid.

    The baseline is the frozen YoY reference: CBS state as of the prior
    fiscal year close (typically 2025-12-31). Once snapshotted it should
    not change. Items 3 (auto-refresh actuals) and 4 (PBT from CBS) both
    compare against this baseline.

    Locks:
      1. data/cbs_baseline.json exists (canonical current)
      2. At least one dated snapshot exists (data/cbs_baseline_*_*_*.json)
      3. Canonical file validates against the schema (delegates to G230)
      4. Snapshot date is within sensible range (1990-01-01 to today+1y)
      5. _schema_version is supported

    Shipped: v10.354.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    canonical = repo / "data" / "cbs_baseline.json"
    if not canonical.exists():
        violations.append(
            "data/cbs_baseline.json missing. Run `python "
            "scripts/snapshot_cbs_baseline.py 2025-12-31` to create it."
        )
        return _baseline_gate_result(violations)

    dated_snapshots = sorted((repo / "data").glob("cbs_baseline_*_*_*.json"))
    if not dated_snapshots:
        violations.append(
            "No dated archive snapshot found (data/cbs_baseline_*_*_*.json)."
        )

    try:
        import json
        baseline = json.loads(canonical.read_text(encoding="utf-8"))
    except Exception as exc:
        violations.append(f"data/cbs_baseline.json unparseable: {exc}")
        return _baseline_gate_result(violations)

    if baseline.get("_schema_version") != "1.0":
        violations.append(
            f"Unsupported schema version: {baseline.get('_schema_version')!r}"
        )

    sd = baseline.get("snapshot_date")
    if not sd:
        violations.append("snapshot_date missing")
    else:
        try:
            from datetime import date as _date
            d = _date.fromisoformat(sd)
            if d.year < 1990 or d.year > _date.today().year + 1:
                violations.append(f"snapshot_date {sd} out of range")
        except Exception as exc:
            violations.append(f"snapshot_date {sd!r} unparseable: {exc}")

    summary = baseline.get("summary", {})
    if "rm_count" not in summary or "branch_count" not in summary:
        violations.append("summary section missing rm_count / branch_count")

    # Schema validation
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        from utils.schema_validator import validate_file
        sv = validate_file("cbs_baseline.json")
        if not sv.get("valid"):
            for err in sv.get("errors", [])[:3]:
                violations.append(f"schema: {err}")
    except Exception as exc:
        violations.append(f"schema validator failed: {exc}")

    return _baseline_gate_result(violations)


