def gate_branch_reconciliation() -> Dict[str, Any]:
    """G255 — v10.369 Per-Branch PBT reconciliation identity.

    Second concrete unification step from the v10.367 architecture arc.
    Replaces the legacy aggregate_cbs_by_branch naive formula with a
    proper allocation engine.

    Locks: Σ(Branch PBT) == Bank PBT  (within KES 100 tolerance)

    Verifies:
      1. utils/branch_pbt_allocator.py present with canonical exports
      2. data/branch_allocation_rules.json present with default_rule
      3. End-to-end probe: seeded bank → Σ(Branch PBT) within tolerance
         of compute_pbt_from_cbs(...).pbt
      4. Multiple branches returned (not just one bucket)

    Shipped: v10.369. Cost: ~0.3s isolated.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — module exports
    alloc_path = repo / "utils" / "branch_pbt_allocator.py"
    if not alloc_path.exists():
        violations.append("utils/branch_pbt_allocator.py missing")
    else:
        text = alloc_path.read_text(encoding="utf-8")
        for sym in ("def compute_pbt_by_branch",
                    "def sum_branch_pbts",
                    "def format_branch_breakdown",
                    "def _load_allocation_rules",
                    "def _aggregate_branches_from_csv",
                    "def _compute_allocation_shares",
                    "def self_test"):
            if sym not in text:
                violations.append(f"branch_pbt_allocator missing {sym}")

    # Check 2 — config
    rules_path = repo / "data" / "branch_allocation_rules.json"
    if not rules_path.exists():
        violations.append("data/branch_allocation_rules.json missing")
    else:
        try:
            import json as _json
            d = _json.loads(rules_path.read_text(encoding="utf-8"))
            if "default_rule" not in d:
                violations.append("branch_allocation_rules.json missing default_rule")
            valid_rules = ("fte_weighted", "revenue_weighted", "equal", "hybrid")
            if d.get("default_rule") not in valid_rules:
                violations.append(
                    f"default_rule '{d.get('default_rule')}' not in {valid_rules}"
                )
        except Exception as exc:
            violations.append(f"branch_allocation_rules.json malformed: {exc}")

    # Check 3 — end-to-end reconciliation probe
    try:
        import sys as _sys
        import tempfile as _tf
        from decimal import Decimal as _Decimal
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if any(m in k for m in (
                "virtual_bank", "pbt_computation", "branch_pbt_allocator",
                "accruals",
            )):
                del _sys.modules[k]
        from utils.virtual_bank_seed import seed_virtual_bank, SeedConfig
        from utils.virtual_bank_cbs_writer import persist_bank_to_cbs
        from utils.pbt_computation import compute_pbt_from_cbs
        from utils.branch_pbt_allocator import (
            compute_pbt_by_branch, sum_branch_pbts,
        )
        bank, _ = seed_virtual_bank(config=SeedConfig.small())
        with _tf.TemporaryDirectory() as td:
            td_path = Path(td)
            persist_bank_to_cbs(bank, output_dir=td_path)
            bank_pbt = compute_pbt_from_cbs(td_path)
            branch_pbts = compute_pbt_by_branch(td_path)
            branch_total = sum_branch_pbts(branch_pbts)

        # Check 4 — multiple branches
        if len(branch_pbts) < 2:
            violations.append(
                f"Only {len(branch_pbts)} branch(es) in result — "
                "allocator may be broken"
            )
        # Identity check
        delta = abs(bank_pbt.pbt - branch_total.pbt)
        TOLERANCE = _Decimal("100")
        if delta > TOLERANCE:
            violations.append(
                f"Σ(Branch PBT) {float(branch_total.pbt):,.0f} != "
                f"Bank PBT {float(bank_pbt.pbt):,.0f}; "
                f"delta {float(delta):,.0f} > tolerance KES {TOLERANCE}"
            )
    except Exception as exc:
        violations.append(
            f"End-to-end branch probe failed: {type(exc).__name__}: {exc}"
        )

    return {
        "id": "G255",
        "name": "branch_reconciliation",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.369 Per-branch PBT reconciliation identity. "
            f"compute_pbt_by_branch returns Dict[str, PBTComponents] keyed "
            f"by branch_code. Σ(Branch PBT) == Bank PBT within KES 100. "
            f"Four allocation rules: fte_weighted (default per Q3), "
            f"revenue_weighted, equal, hybrid. Admin-configurable in "
            f"data/branch_allocation_rules.json. Replaces legacy "
            f"aggregate_cbs_by_branch naive formula. "
            f"{len(violations)} violations"
        ),
    }


