def gate_role_taxonomy_alignment() -> Dict[str, Any]:
    """G260 — v10.374 Role Taxonomy Alignment.

    First batch of Phase A from the v10.373 system state review. Joshua's
    directive: "ensure the tree also aligns from the pipeline management
    ... constantly zoom out and review the system as a whole".

    Locks the profitability axis: every role in users.json + hr.json
    must classify to one of {portfolio_owner, proposition_owner,
    structural_owner, service, support} — orthogonal to the existing
    seniority axis (role_tiers in org_hierarchy_config.json).

    Verifies:
      1. utils/role_taxonomy.py present with canonical exports
      2. data/org_hierarchy_config.json has the profitability_axis subtree
         with role_classification + tier_keyword_fallback
      3. validate_role_coverage returns 0 unclassified roles
         (every role in users.json + hr.json must classify either
         explicitly or via keyword fallback)
      4. Five tier constants and seven SBU constants are exported
      5. SBU values align with segment_sbu_mapping.json
      6. can_be_tagged returns True only for portfolio_owner + service
         (proposition / structural / support roles MUST NOT tag accounts)

    Shipped: v10.374. Cost: ~0.05s isolated.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — module exports
    mod_path = repo / "utils" / "role_taxonomy.py"
    if not mod_path.exists():
        violations.append("utils/role_taxonomy.py missing")
    else:
        text = mod_path.read_text(encoding="utf-8")
        for sym in ("def classify_role",
                    "def get_profitability_tier",
                    "def get_branch_scope",
                    "def get_sbu",
                    "def can_be_tagged",
                    "def list_all_classified_roles",
                    "def list_roles_by_tier",
                    "def list_roles_by_sbu",
                    "def validate_role_coverage",
                    "def self_test",
                    "class RoleClassification",
                    "TIER_PORTFOLIO_OWNER",
                    "TIER_PROPOSITION_OWNER",
                    "TIER_STRUCTURAL_OWNER",
                    "TIER_SERVICE",
                    "TIER_SUPPORT"):
            if sym not in text:
                violations.append(f"role_taxonomy missing {sym}")

    # Check 2 — config present
    cfg_path = repo / "data" / "org_hierarchy_config.json"
    if not cfg_path.exists():
        violations.append("data/org_hierarchy_config.json missing")
    else:
        try:
            import json as _json
            d = _json.loads(cfg_path.read_text(encoding="utf-8"))
            axis = d.get("profitability_axis", {})
            if not axis:
                violations.append("org_hierarchy_config.json missing profitability_axis subtree")
            for k in ("role_classification", "tier_keyword_fallback",
                      "tiers", "branch_scopes", "_validation_rules"):
                if k not in axis:
                    violations.append(f"profitability_axis missing {k}")
            rc = axis.get("role_classification", {})
            if len(rc) < 30:
                violations.append(
                    f"role_classification has only {len(rc)} entries; "
                    f"expected ≥30 for canonical mapping coverage"
                )
        except Exception as exc:
            violations.append(f"org_hierarchy_config.json malformed: {exc}")

    # Check 3 — coverage = 100%
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if "role_taxonomy" in k:
                del _sys.modules[k]
        from utils.role_taxonomy import (
            validate_role_coverage, can_be_tagged,
            classify_role, ALL_TIERS, ALL_SBUS, ALL_SCOPES,
            TIER_PORTFOLIO_OWNER, TIER_SERVICE,
            TIER_PROPOSITION_OWNER, TIER_STRUCTURAL_OWNER, TIER_SUPPORT,
        )
        cov = validate_role_coverage()
        if cov["default"] > 0:
            violations.append(
                f"{cov['default']} roles fall to no_match_default: "
                f"{cov['unclassified'][:5]}... — add to role_classification or "
                f"tier_keyword_fallback"
            )

        # Check 4 — constants
        if len(ALL_TIERS) != 5:
            violations.append(f"ALL_TIERS has {len(ALL_TIERS)} entries, expected 5")
        if len(ALL_SBUS) != 7:
            violations.append(f"ALL_SBUS has {len(ALL_SBUS)} entries, expected 7")
        if len(ALL_SCOPES) != 3:
            violations.append(f"ALL_SCOPES has {len(ALL_SCOPES)} entries, expected 3")

        # Check 5 — SBU alignment with segment_sbu_mapping.json
        seg_path = repo / "data" / "segment_sbu_mapping.json"
        if seg_path.exists():
            seg = _json.loads(seg_path.read_text(encoding="utf-8"))
            known_sbus = set()
            for v in seg.get("segment_to_sbu", {}).values():
                if isinstance(v, str):
                    known_sbus.add(v)
            # SBUs used in role_taxonomy must be a subset of the mapping or
            # be axis-level operational/support SBUs (Treasury / Digital_Agency
            # / Support / Executive don't appear in segment_to_sbu because
            # they're not customer-facing segments).
            extra = (set(ALL_SBUS) - known_sbus -
                     {"Support", "Executive", "Digital_Agency",
                      "Digital/Agency", "Treasury"})
            if extra:
                violations.append(
                    f"role_taxonomy SBU constants not in segment_sbu_mapping: {extra}"
                )

        # Check 6 — taggability invariant
        for role in ("Branch Manager", "Managing Director", "Head Of Women Banking",
                     "Compliance Officer"):
            if can_be_tagged(role):
                violations.append(
                    f"Role '{role}' incorrectly classified as taggable; "
                    f"only portfolio_owner + service tiers should be taggable"
                )
        for role in ("Relationship Officer-Personal Banker", "Teller",
                     "Relationship Manager - Corporate Banking"):
            if not can_be_tagged(role):
                violations.append(
                    f"Role '{role}' should be taggable but is not"
                )
    except Exception as exc:
        violations.append(
            f"Role taxonomy probe failed: {type(exc).__name__}: {exc}"
        )

    return {
        "id": "G260",
        "name": "role_taxonomy_alignment",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.374 Role Taxonomy Alignment. Profitability axis "
            f"(portfolio_owner / proposition_owner / structural_owner / "
            f"service / support) — orthogonal to seniority axis. Every "
            f"role in users.json + hr.json (126 distinct) must classify "
            f"explicitly or via keyword fallback. Taggability invariant: "
            f"only portfolio_owner + service roles may appear in "
            f"accounts.csv::relationship_manager_code. First batch of "
            f"Phase A from v10.373 system review. {len(violations)} violations"
        ),
    }


