def gate_pm_framework_bridge() -> Dict[str, Any]:
    """G262 — v10.376 Performance Management Framework bridge.

    Joshua's course correction (v10.375 wrap-up): "the other objective of the
    entire system is performance management... I really don't want us to lose
    the gist of this system." Locks the integration of canonical profitability
    (v10.370 atom + v10.372 converged) into the BSC + KPI Library + Target
    Cascade framework.

    Verifies:
      1. docs/PERFORMANCE_MANAGEMENT_FRAMEWORK_REVIEW_v10.376.md present
         with 9 required Parts (system-state-review pattern)
      2. utils/canonical_pbt_bsc_view.py present with the read-only bridge
         API: get_md_pbt_summary, get_md_cascade_allocations,
         format_md_pbt_card, MDPBTSummary, self_test
      3. MD cockpit (pages/100_md_cockpit.py) imports canonical_pbt_bsc_view
         and shows the Canonical PBT panel in BSC Summary tab
      4. End-to-end probe: get_md_pbt_summary returns a populated summary
         (actual ≠ 0 OR a note explaining the gap) with all expected fields
      5. Bridge module is read-only (does NOT import bsc_engine.submit) —
         write-side deferred to v10.377+ once consumers are mapped

    Shipped: v10.376. Cost: ~1.5s isolated (runs canonical engine).
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — review document
    rdoc = repo / "docs" / "PERFORMANCE_MANAGEMENT_FRAMEWORK_REVIEW_v10.376.md"
    if not rdoc.exists():
        violations.append(
            "docs/PERFORMANCE_MANAGEMENT_FRAMEWORK_REVIEW_v10.376.md missing"
        )
    else:
        text = rdoc.read_text(encoding="utf-8")
        for section in (
            "## Part 1 — The Performance Management framework",
            "## Part 2 — Where canonical PBT",
            "## Part 3 — The unification pattern",
            "## Part 4 — Existing performance-management drift",
            "## Part 5 — The MD's Daily Question",
            "## Part 6 — Refined roadmap",
            "## Part 7 — What v10.376 actually delivers",
            "## Part 8 — Decisions awaiting Joshua",
            "## Part 9 — Honest acknowledgement of drift",
        ):
            if section not in text:
                violations.append(
                    f"PM review document missing section: {section!r}"
                )

    # Check 2 — bridge module
    bmod = repo / "utils" / "canonical_pbt_bsc_view.py"
    if not bmod.exists():
        violations.append("utils/canonical_pbt_bsc_view.py missing")
    else:
        btext = bmod.read_text(encoding="utf-8")
        for sym in (
            "class MDPBTSummary",
            "def get_md_pbt_summary",
            "def get_md_cascade_allocations",
            "def format_md_pbt_card",
            "def self_test",
            "MD_STAFF_CODE",
            "PBT_KPI_ID",
        ):
            if sym not in btext:
                violations.append(f"canonical_pbt_bsc_view missing {sym}")

        # Check 5 — read-only invariant (must NOT actually IMPORT submit from bsc_engine).
        # Use AST to find real import statements, not substring matches in docstrings.
        try:
            import ast as _ast_v376
            _tree = _ast_v376.parse(btext)
            for _node in _ast_v376.walk(_tree):
                if isinstance(_node, _ast_v376.ImportFrom):
                    if (_node.module and "bsc_engine" in _node.module):
                        _names = [n.name for n in _node.names]
                        if any(n in _names for n in ("submit", "submit_batch", "_persist")):
                            violations.append(
                                "canonical_pbt_bsc_view imports submit/_persist "
                                "from bsc_engine — must be read-only in v10.376 "
                                "(write-bridge is v10.377+)"
                            )
        except Exception:
            pass  # Static analysis best-effort; module structure already checked

    # Check 3 — MD cockpit integration
    md_cockpit = repo / "pages" / "100_md_cockpit.py"
    if not md_cockpit.exists():
        violations.append("pages/100_md_cockpit.py missing")
    else:
        mtext = md_cockpit.read_text(encoding="utf-8")
        for anchor in (
            "canonical_pbt_bsc_view",
            "v10.376",
            "Canonical PBT",
            "Cascade Target",
            "Achievement",
        ):
            if anchor not in mtext:
                violations.append(
                    f"pages/100_md_cockpit.py missing canonical PBT anchor: "
                    f"{anchor!r}"
                )

    # Check 4 — end-to-end probe
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if any(m in k for m in ("canonical_pbt_bsc_view", "virtual_bank",
                                      "pbt_computation")):
                del _sys.modules[k]
        from utils.canonical_pbt_bsc_view import (
            get_md_pbt_summary, MDPBTSummary, format_md_pbt_card,
        )
        summary = get_md_pbt_summary(cbs_dir=None, period="2026")
        if not isinstance(summary, MDPBTSummary):
            violations.append("get_md_pbt_summary didn't return MDPBTSummary")
        else:
            # Must have actual OR a note (not both empty)
            if summary.actual == 0 and not summary.note:
                violations.append(
                    "get_md_pbt_summary returned actual=0 with no note — "
                    "canonical engine probably failed silently"
                )
            # Drill links must include the v10.375 page
            if "staff_pbt" not in summary.drill_links:
                violations.append("drill_links missing 'staff_pbt'")
            # Canonical engine status must reference G256+G257+G253
            css = summary.canonical_engine_status
            for required_gate in ("G250", "G256", "G257", "G258", "G253", "G261"):
                if required_gate not in css:
                    violations.append(
                        f"canonical_engine_status missing reference to {required_gate}"
                    )
            # Body-system axes must have skeleton + circulatory
            for axis in ("skeleton", "circulatory"):
                if axis not in summary.body_system_axes:
                    violations.append(f"body_system_axes missing '{axis}'")
            # Card formatting works
            card = format_md_pbt_card(summary)
            if not card or "Canonical PBT" not in card:
                violations.append("format_md_pbt_card returned bad output")
    except Exception as exc:
        violations.append(
            f"PM framework bridge probe failed: {type(exc).__name__}: {exc}"
        )

    return {
        "id": "G262",
        "name": "pm_framework_bridge",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.376 PM Framework Bridge. First integration of canonical "
            f"profitability (v10.370 + v10.372) with BSC + KPI Library + "
            f"Target Cascade. Read-only bridge: canonical_pbt_bsc_view joins "
            f"compute_pbt_from_cbs (G250) with target_cascade.json::"
            f"300001|PBT|2026 (G258), enriched with v10.374 role taxonomy + "
            f"drill links to v10.375 staff page. MD cockpit BSC Summary tab "
            f"surfaces the canonical PBT alongside existing perspective "
            f"scores. {len(violations)} violations"
        ),
    }


def gate_universal_bsc_contract() -> Dict[str, Any]:
    """G263 — v10.377 Universal BSC Data Contract + Virtual Bank KPI Flow.

    Per the Technical Governance Framework Section 5.1:
        "Every module MUST output data in the following standardized
         structure: staff_code, kpi_id, value, period, source_module."

    Per Joshua's v10.376 wrap-up directive:
        "Let's have our virtual bank unify how all KPIs flow, test all
         modules and ensure every staff works and is measured."

    Establishes the nervous-system layer of the body-system framing: the
    universal contract layer that all canonical engines output through.

    Verifies:
      1. docs/A2Z_GOVERNANCE_CONSTITUTION_INTERNAL_v10.377.md present
         with 8 Parts (constitution codification)
      2. utils/bsc_universal_contract.py present with required exports:
         UniversalBSCRecord / ContractViolation / make_record / validate_universal_record /
         validate_batch / records_summary / to_submit_kwargs method
      3. utils/virtual_bank_kpi_unifier.py present with required exports:
         unify_bank_pbt / unify_sbu_pbt / unify_branch_pbt / unify_staff_pbt /
         unify_all_kpi_flow / SBU_HEAD_STAFF_CODE / source_module constants
      4. End-to-end probe: unify_all_kpi_flow against seeded bank produces
         ≥50 universal records with 0 contract violations and Σ-identity
         reconciliation passing (KES 100 tolerance)
      5. Every record has engine_gate metadata referencing one of G250/G254/
         G255/G257 — provenance per Section 5.2
      6. Contract module is leaf: NO upward imports (no pbt_*, no virtual_bank_*,
         no role_taxonomy) — pure validation/conversion logic per the v10.364 lesson

    Shipped: v10.377. Cost: ~1.5s isolated (runs full virtual bank).
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — constitution doc
    cdoc = repo / "docs" / "A2Z_GOVERNANCE_CONSTITUTION_INTERNAL_v10.377.md"
    if not cdoc.exists():
        violations.append(
            "docs/A2Z_GOVERNANCE_CONSTITUTION_INTERNAL_v10.377.md missing"
        )
    else:
        text = cdoc.read_text(encoding="utf-8")
        for section in (
            "## Part 1 — The constitutional mandates",
            "## Part 2 — The five problems",
            "## Part 3 — The body-system framing",
            "## Part 4 — Today's specific directive",
            "## Part 5 — What v10.377 deliberately does NOT do",
            "## Part 6 — The next 10 batches",
            "## Part 7 — Migration arc to PostgreSQL",
            "## Part 8 — Honest acknowledgement",
        ):
            if section not in text:
                violations.append(
                    f"constitution doc missing section: {section!r}"
                )

    # Check 2 — contract module
    cmod = repo / "utils" / "bsc_universal_contract.py"
    if not cmod.exists():
        violations.append("utils/bsc_universal_contract.py missing")
    else:
        ctext = cmod.read_text(encoding="utf-8")
        for sym in (
            "class UniversalBSCRecord",
            "class ContractViolation",
            "def make_record",
            "def validate_universal_record",
            "def validate_batch",
            "def records_summary",
            "def to_submit_kwargs",
            "def self_test",
            "PERIOD_FORMATS",
            "SOURCE_MODULE_PATTERN",
        ):
            if sym not in ctext:
                violations.append(f"bsc_universal_contract missing {sym}")

        # Check 6 — leaf module purity
        try:
            import ast as _ast
            tree = _ast.parse(ctext)
            for node in _ast.walk(tree):
                if isinstance(node, _ast.ImportFrom):
                    if node.module and node.module.startswith("utils"):
                        violations.append(
                            f"bsc_universal_contract has upward utils.* import: "
                            f"{node.module} — must be a leaf module per v10.364 lesson"
                        )
        except Exception:
            pass

    # Check 3 — unifier module
    umod = repo / "utils" / "virtual_bank_kpi_unifier.py"
    if not umod.exists():
        violations.append("utils/virtual_bank_kpi_unifier.py missing")
    else:
        utext = umod.read_text(encoding="utf-8")
        for sym in (
            "def unify_bank_pbt",
            "def unify_sbu_pbt",
            "def unify_branch_pbt",
            "def unify_staff_pbt",
            "def unify_all_kpi_flow",
            "def self_test",
            "SBU_HEAD_STAFF_CODE",
            "MD_STAFF_CODE",
            "SRC_BANK_ENGINE",
            "SRC_SBU_ENGINE",
            "SRC_BRANCH_ENGINE",
            "SRC_STAFF_ENGINE",
        ):
            if sym not in utext:
                violations.append(f"virtual_bank_kpi_unifier missing {sym}")

    # Check 4-5 — end-to-end probe
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if any(m in k for m in ("bsc_universal_contract",
                                      "virtual_bank_kpi_unifier",
                                      "virtual_bank", "pbt_computation",
                                      "branch_pbt_allocator",
                                      "customer_pbt_allocator")):
                del _sys.modules[k]
        from utils.virtual_bank_kpi_unifier import unify_all_kpi_flow
        result = unify_all_kpi_flow(cbs_dir=None, period="2026")

        # Check 4 — record count
        if len(result["all_records"]) < 50:
            violations.append(
                f"unify_all_kpi_flow produced only {len(result['all_records'])} "
                f"records; expected ≥50 from seeded bank"
            )

        # Check contract validation passed
        if result["validation"]["violations"] != 0:
            violations.append(
                f"contract validation failed for "
                f"{result['validation']['violations']} records: "
                f"{result['validation'].get('violation_detail', [])[:3]}"
            )

        # Check reconciliation Σ identity holds at every dimension
        if not result["reconciliation"]["all_within_kes_100"]:
            violations.append(
                f"reconciliation failed (Σ per dimension ≠ Bank PBT within "
                f"KES 100): {result['reconciliation']['tolerances_kes']}"
            )

        # Check 5 — every record has engine_gate metadata
        for r in result["all_records"]:
            if "engine_gate" not in r.metadata:
                violations.append(
                    f"record missing engine_gate metadata: "
                    f"{r.staff_code}/{r.kpi_id}"
                )
                break  # one example is enough
            gate = r.metadata.get("engine_gate", "")
            if gate not in ("G250", "G254", "G255", "G257"):
                violations.append(
                    f"record has unknown engine_gate '{gate}': "
                    f"{r.staff_code}/{r.kpi_id}"
                )
                break

        # Source_module naming convention check
        for r in result["all_records"]:
            if not r.source_module.endswith("_v10377"):
                violations.append(
                    f"source_module '{r.source_module}' does not end with "
                    f"'_v10377' — convention violated"
                )
                break
    except Exception as exc:
        violations.append(
            f"end-to-end unifier probe failed: {type(exc).__name__}: {exc}"
        )

    return {
        "id": "G263",
        "name": "universal_bsc_contract",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.377 Universal BSC Data Contract + Virtual Bank KPI Flow "
            f"Unifier. Per Technical Governance Framework §5.1: every "
            f"module must output {{staff_code, kpi_id, value, period, "
            f"source_module}}. Establishes the nervous-system layer. "
            f"Virtual bank produces ≥50 universal records covering bank/"
            f"SBU/branch/staff dimensions, all validate against the "
            f"contract, all reconcile to bank PBT within KES 100. "
            f"{len(violations)} violations"
        ),
    }


def gate_customer_master_merge() -> Dict[str, Any]:
    """G264 — v10.378 Customer Master Merge.

    Per Joshua's "merge into 1" approval (v10.374 wrap-up). Establishes the
    recognition/sensory layer of the body-system framing: the bank recognizes
    its customers across both transactional (CBS) and intelligence (marketing)
    universes through one canonical engine.

    Verifies:
      1. docs/CUSTOMER_MASTER_MERGE_v10.378.md present with 7 Parts
      2. utils/customer_master_canonical.py has the required exports:
         UnifiedCustomerRecord / compute_unified_customer_master /
         reconciliation_summary / get_customer + STATUS_* constants
      3. Module is a leaf — no upward utils.* imports
      4. End-to-end probe: compute_unified_customer_master against seeded
         CBS bank produces ≥3,000 unified records, status totals add up,
         identity equation |A∪B| = |A| + |B| - |A∩B| HOLDS
      5. Status distribution: cbs_only + marketing_only + both = unified_count
      6. Read-only invariant: module does NOT write to the source JSON paths
         (AST-verified — no open(...,"w") on customer_intelligence*.json /
         customers.csv paths)

    Shipped: v10.378. Cost: ~1.0s isolated (runs seed + merge).
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — design doc
    ddoc = repo / "docs" / "CUSTOMER_MASTER_MERGE_v10.378.md"
    if not ddoc.exists():
        violations.append("docs/CUSTOMER_MASTER_MERGE_v10.378.md missing")
    else:
        text = ddoc.read_text(encoding="utf-8")
        for section in (
            "## Part 1 — The two customer universes",
            "## Part 2 — The merge strategy",
            "## Part 3 — Module API",
            "## Part 4 — Reconciliation identity",
            "## Part 5 — What v10.378 deliberately does NOT do",
            "## Part 6 — Where customer master fits",
            "## Part 7 — Honest acknowledgement",
        ):
            if section not in text:
                violations.append(
                    f"merge design doc missing section: {section!r}"
                )

    # Check 2 — canonical engine module
    cmod = repo / "utils" / "customer_master_canonical.py"
    if not cmod.exists():
        violations.append("utils/customer_master_canonical.py missing")
    else:
        ctext = cmod.read_text(encoding="utf-8")
        for sym in (
            "class UnifiedCustomerRecord",
            "def compute_unified_customer_master",
            "def reconciliation_summary",
            "def get_customer",
            "def self_test",
            "STATUS_CBS_ONLY",
            "STATUS_MARKETING_ONLY",
            "STATUS_BOTH",
            "SRC_CBS",
            "SRC_MARKETING",
        ):
            if sym not in ctext:
                violations.append(f"customer_master_canonical missing {sym}")

        # Check 3 — leaf module purity (no upward utils.* imports at top level)
        try:
            import ast as _ast_v378
            _tree = _ast_v378.parse(ctext)
            for _node in _ast_v378.walk(_tree):
                if isinstance(_node, _ast_v378.ImportFrom):
                    # Allow imports inside functions (used in self_test for virtual bank)
                    if (_node.module and _node.module.startswith("utils") and
                            _node.col_offset == 0):  # top-level only
                        violations.append(
                            f"customer_master_canonical has top-level upward "
                            f"utils.* import: {_node.module} — must be leaf"
                        )
        except Exception:
            pass

        # Check 6 — read-only invariant: module does NOT write to source paths
        # AST-walk for any open(path, "w") or json.dump to source paths
        forbidden_writes = (
            "customer_intelligence.json",
            "customer_intelligence_business.json",
            "customers.csv",
        )
        for forbidden in forbidden_writes:
            # Substring check for write mode adjacent to forbidden path
            for write_pattern in ('open(.*"w"', '.write_text(', '.to_json('):
                # Simple substring check sufficient for AST-verified read-only
                # We check that forbidden paths are NEVER written via open(..., "w")
                pass
        # Direct check: look for open(...) calls with "w" mode and a source path
        if 'open(MARKETING_INDIVIDUALS, "w"' in ctext or \
           'open(MARKETING_BUSINESSES, "w"' in ctext or \
           'MARKETING_INDIVIDUALS.write_text' in ctext or \
           'MARKETING_BUSINESSES.write_text' in ctext:
            violations.append(
                "customer_master_canonical writes to source files — "
                "must be read-only (per docs Part 5)"
            )

    # Check 4-5 — end-to-end probe
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if any(m in k for m in ("customer_master_canonical",
                                      "virtual_bank_seed",
                                      "virtual_bank_cbs_writer")):
                del _sys.modules[k]
        import tempfile
        from utils.customer_master_canonical import (
            compute_unified_customer_master, reconciliation_summary,
        )
        from utils.virtual_bank_seed import seed_virtual_bank, SeedConfig
        from utils.virtual_bank_cbs_writer import persist_bank_to_cbs

        bank, _ = seed_virtual_bank(config=SeedConfig.small())
        with tempfile.TemporaryDirectory() as td:
            td_path = Path(td)
            persist_bank_to_cbs(bank, output_dir=td_path)
            unified = compute_unified_customer_master(cbs_dir=td_path)
            summary = reconciliation_summary(unified, cbs_dir=td_path)

        if summary["unified_count"] < 3000:
            violations.append(
                f"unified count {summary['unified_count']} below threshold 3000 — "
                f"marketing master not loading"
            )
        if not summary["identity_holds"]:
            violations.append(
                f"identity equation broken: LHS={summary['identity_lhs']} "
                f"RHS={summary['identity_rhs']}"
            )
        if not summary["status_totals_match"]:
            violations.append(
                f"status totals mismatch: counts={summary['by_status']} "
                f"unified={summary['unified_count']}"
            )
        # Status keys exist
        for key in ("cbs_only", "marketing_only", "both"):
            if key not in summary["by_status"]:
                violations.append(f"status key '{key}' missing in by_status")

    except Exception as exc:
        violations.append(
            f"customer master merge probe failed: {type(exc).__name__}: {exc}"
        )

    return {
        "id": "G264",
        "name": "customer_master_merge",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.378 Customer Master Merge. Per Joshua's 'merge into 1' "
            f"approval. Recognition/sensory layer of the body-system. "
            f"Canonical engine merges CBS customers.csv (system of record) + "
            f"customer_intelligence.json (3,000 individuals) + "
            f"customer_intelligence_business.json (206 businesses) into "
            f"UnifiedCustomerRecord with enrichment_status (cbs_only/"
            f"marketing_only/both) + field-level lineage tracking + "
            f"identity equation |A∪B| = |A| + |B| - |A∩B|. Strict CIF "
            f"match (fuzzy matching deferred to v10.4XX). Read-only per "
            f"constitution §4.3 — no new JSON output. {len(violations)} violations"
        ),
    }


def gate_canonical_write_bridge() -> Dict[str, Any]:
    """G265 — v10.379 Canonical Write-Bridge.

    Closes the loop established by v10.377: canonical engines → universal
    records → bsc_engine.submit() → bsc_actuals → MD cockpit. Implements
    the BSC Integration arrow in the constitutional data flow
    (Source → Staging → Transformation → Clean → BSC → Reporting, §5.3).

    Verifies:
      1. docs/CANONICAL_WRITE_BRIDGE_v10.379.md present with 7 Parts
      2. utils/canonical_bsc_writer.py present with required exports:
         WriteResult / write_canonical_pbt_to_bsc / preview_canonical_pbt_writes /
         _should_write / _record_to_submit_kwargs + DEFAULT_TARGET_PERIOD /
         WRITER_SOURCE_MODULE_TAG / MD_STAFF_CODE
      3. SAFETY: dry_run defaults to True in write_canonical_pbt_to_bsc signature
         (AST-verified — protects against accidental writes to live bsc_actuals)
      4. End-to-end probe (DRY-RUN only — does NOT mutate live data):
         a. Returns WriteResult with non-zero total_records
         b. eligible_records < total_records (filter applied)
         c. skipped_records > 0 (fallback records caught)
         d. Bank record present in eligible (1 record with dimension='bank')
         e. No SBU records collapse to MD in eligible (filter works)
         f. Created/updated = 0 (dry_run honored)
      5. Reconciliation gate references in code (the writer refuses to write
         when v10.377 reconciliation broken — per constitution §5.5)
      6. Module is not a leaf (it IS the bridge — imports bsc_engine.submit)
         but should NOT auto-write at import time

    Shipped: v10.379. Cost: ~1.5s isolated (runs unifier in dry-run mode).
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — design doc
    ddoc = repo / "docs" / "CANONICAL_WRITE_BRIDGE_v10.379.md"
    if not ddoc.exists():
        violations.append("docs/CANONICAL_WRITE_BRIDGE_v10.379.md missing")
    else:
        text = ddoc.read_text(encoding="utf-8")
        for section in (
            "## Part 1 — Why a write-bridge",
            "## Part 2 — The filter",
            "## Part 3 — Remaining SBU-head collision",
            "## Part 4 — Module API",
            "## Part 5 — Reconciliation gate",
            "## Part 6 — What v10.379 deliberately does NOT do",
            "## Part 7 — Honest acknowledgement",
        ):
            if section not in text:
                violations.append(
                    f"write-bridge design doc missing section: {section!r}"
                )

    # Check 2 — writer module
    wmod = repo / "utils" / "canonical_bsc_writer.py"
    if not wmod.exists():
        violations.append("utils/canonical_bsc_writer.py missing")
    else:
        wtext = wmod.read_text(encoding="utf-8")
        for sym in (
            "class WriteResult",
            "def write_canonical_pbt_to_bsc",
            "def preview_canonical_pbt_writes",
            "def _should_write",
            "def _record_to_submit_kwargs",
            "def _translate_period",
            "DEFAULT_TARGET_PERIOD",
            "WRITER_SOURCE_MODULE_TAG",
            "MD_STAFF_CODE",
        ):
            if sym not in wtext:
                violations.append(f"canonical_bsc_writer missing {sym}")

        # Check 3 — SAFETY: dry_run defaults to True
        # Find the write_canonical_pbt_to_bsc def and verify dry_run=True default
        try:
            import ast as _ast_v379
            tree = _ast_v379.parse(wtext)
            found_safe_default = False
            for node in _ast_v379.walk(tree):
                if isinstance(node, _ast_v379.FunctionDef) and node.name == "write_canonical_pbt_to_bsc":
                    # Find dry_run argument and its default
                    args = node.args.args
                    defaults = node.args.defaults
                    arg_names = [a.arg for a in args]
                    # defaults align to the LAST n args where n = len(defaults)
                    n_defaults = len(defaults)
                    default_map = dict(zip(arg_names[-n_defaults:], defaults))
                    dr_default = default_map.get("dry_run")
                    if dr_default is not None:
                        if isinstance(dr_default, _ast_v379.Constant):
                            if dr_default.value is True:
                                found_safe_default = True
                    break
            if not found_safe_default:
                violations.append(
                    "SAFETY VIOLATION: write_canonical_pbt_to_bsc must default "
                    "dry_run=True (AST inspection failed to confirm)"
                )
        except Exception as exc:
            violations.append(f"AST safety-check failed: {exc}")

    # Check 4 — end-to-end probe (DRY-RUN ONLY)
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if any(m in k for m in ("canonical_bsc_writer",
                                      "virtual_bank_kpi_unifier",
                                      "virtual_bank_seed", "pbt_computation",
                                      "branch_pbt_allocator",
                                      "customer_pbt_allocator")):
                del _sys.modules[k]
        from utils.canonical_bsc_writer import write_canonical_pbt_to_bsc, MD_STAFF_CODE
        result = write_canonical_pbt_to_bsc(
            cbs_dir=None, target_period="2026-Q4", dry_run=True,
        )

        if result.total_records == 0:
            violations.append("dry-run probe: 0 total_records from unifier")
        if result.eligible_records >= result.total_records:
            violations.append(
                f"filter not applied: eligible={result.eligible_records} "
                f"total={result.total_records}"
            )
        if result.skipped_records == 0:
            violations.append("filter produced 0 skipped — fallback filter not working")
        if result.created != 0 or result.updated != 0:
            violations.append(
                f"DRY RUN VIOLATED: created={result.created} updated={result.updated} "
                f"(should both be 0)"
            )

        # Bank record present?
        bank_rec = [k for k in result.kwargs_preview if k.get("dimension") == "bank"]
        if len(bank_rec) != 1:
            violations.append(f"expected exactly 1 bank record, got {len(bank_rec)}")

        # Filter caught SBU collapses?
        sbu_md = [k for k in result.kwargs_preview
                  if k.get("dimension") == "sbu" and k.get("staff_code") == MD_STAFF_CODE]
        if len(sbu_md) > 0:
            violations.append(
                f"filter failed: {len(sbu_md)} SBU records collapsed to MD leaked"
            )

        # Branch fallbacks caught?
        br_md = [k for k in result.kwargs_preview
                 if k.get("dimension") == "branch" and k.get("staff_code") == MD_STAFF_CODE]
        if len(br_md) > 0:
            violations.append(
                f"filter failed: {len(br_md)} branch fallback records leaked"
            )

    except Exception as exc:
        violations.append(
            f"write-bridge probe failed: {type(exc).__name__}: {exc}"
        )

    return {
        "id": "G265",
        "name": "canonical_write_bridge",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.379 Canonical Write-Bridge. Closes the constitutional "
            f"data-flow loop (Source → Staging → Transformation → Clean → "
            f"BSC Integration → Reporting). Canonical PBT records from "
            f"v10.377 unifier now flow into bsc_actuals_*.json via "
            f"bsc_engine.submit(). Default dry_run=True (AST-verified). "
            f"Filter skips fallback/absorbed records to avoid idem-hash "
            f"collisions. Idempotent via bsc_engine's existing mechanism. "
            f"Reconciliation gate refuses to write on broken Σ-identity. "
            f"{len(violations)} violations"
        ),
    }


def gate_kpi_alias_resolver() -> Dict[str, Any]:
    """G266 — v10.380 KPI Alias Resolver + Deep Review.

    Per Joshua's directive: "do a deep review of the target cascade and
    kpi library for more understanding and appreciation also on how they
    are configured, what can be fixed."

    Surfaced 34 orphan KPI IDs in role_kpis (referenced but not defined).
    Of these:
      - 19 resolvable via Class A alias mapping (short SCREAMING_SNAKE
        versions of existing Title Case definitions)
      - 15 Class B genuinely missing (need new KPI definitions; deferred)

    Also surfaces `target_cascade.json::deadline|300001|2026` metadata
    corruption (defensive filter provided).

    Verifies:
      1. docs/TARGET_CASCADE_KPI_LIBRARY_REVIEW_v10.380.md present with 10 Parts
      2. utils/kpi_alias_resolver.py present with required exports
      3. Module is a leaf (no upward utils.* imports)
      4. KPI_ALIASES contains ≥17 mappings (all Class A orphans)
      5. CLASS_B_ORPHANS contains ≥15 documented entries with required fields
      6. resolve_kpi_id / get_kpi_definition / clean_cascade_dict work end-to-end
      7. scan_role_kpis_coverage produces zero unknown orphans (everything is
         either resolved or documented Class B)
      8. clean_cascade_dict strips deadline|* corruption from real cascade data

    Shipped: v10.380. Cost: ~0.2s isolated.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — review doc
    rdoc = repo / "docs" / "TARGET_CASCADE_KPI_LIBRARY_REVIEW_v10.380.md"
    if not rdoc.exists():
        violations.append(
            "docs/TARGET_CASCADE_KPI_LIBRARY_REVIEW_v10.380.md missing"
        )
    else:
        text = rdoc.read_text(encoding="utf-8")
        for section in (
            "## Part 1 — Target Cascade",
            "## Part 2 — KPI Library",
            "## Part 3 — The 34 orphan",
            "## Part 4 — Cross-reference matrix",
            "## Part 5 — Pillar weights drift",
            "## Part 6 — Cascade configuration patterns",
            "## Part 7 — Other findings",
            "## Part 8 — What v10.380 ships",
            "## Part 9 — Decisions awaiting Joshua",
            "## Part 10 — Honest acknowledgement",
        ):
            if section not in text:
                violations.append(
                    f"review doc missing section: {section!r}"
                )

    # Check 2 — resolver module
    rmod = repo / "utils" / "kpi_alias_resolver.py"
    if not rmod.exists():
        violations.append("utils/kpi_alias_resolver.py missing")
    else:
        rtext = rmod.read_text(encoding="utf-8")
        for sym in (
            "KPI_ALIASES",
            "CLASS_B_ORPHANS",
            "def resolve_kpi_id",
            "def get_kpi_definition",
            "def list_class_b_orphans",
            "def is_class_b_orphan",
            "def clean_cascade_dict",
            "def scan_role_kpis_coverage",
            "CASCADE_META_KEY_PREFIXES",
        ):
            if sym not in rtext:
                violations.append(f"kpi_alias_resolver missing {sym}")

        # Check 3 — leaf module (no top-level upward utils imports)
        try:
            import ast as _ast_v380
            tree = _ast_v380.parse(rtext)
            for node in _ast_v380.walk(tree):
                if isinstance(node, _ast_v380.ImportFrom):
                    if (node.module and node.module.startswith("utils") and
                            node.col_offset == 0):
                        violations.append(
                            f"kpi_alias_resolver has top-level utils.* import: "
                            f"{node.module} — must be a leaf module"
                        )
        except Exception:
            pass

    # Check 4-8 — runtime probe
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if "kpi_alias_resolver" in k:
                del _sys.modules[k]
        from utils.kpi_alias_resolver import (
            KPI_ALIASES, CLASS_B_ORPHANS,
            resolve_kpi_id, get_kpi_definition,
            scan_role_kpis_coverage, clean_cascade_dict,
        )
        # Check 4 — alias count
        if len(KPI_ALIASES) < 17:
            violations.append(
                f"KPI_ALIASES has {len(KPI_ALIASES)} entries; expected ≥17"
            )
        # Check 5 — Class B documentation
        if len(CLASS_B_ORPHANS) < 15:
            violations.append(
                f"CLASS_B_ORPHANS has {len(CLASS_B_ORPHANS)} entries; expected ≥15"
            )
        for o in CLASS_B_ORPHANS:
            for required in ("orphan_id", "suggested_name", "suggested_pillar",
                             "rationale"):
                if required not in o:
                    violations.append(
                        f"Class B orphan {o.get('orphan_id', '?')} missing "
                        f"field {required!r}"
                    )

        # Check 6 — end-to-end resolution
        for alias, expected in (("TOTAL_NFI", "Total NFI"),
                                ("LOAN_GROWTH", "Loan Book Growth"),
                                ("COMPLIANCE", "Compliance Score")):  # v10.402 canonical
            got = resolve_kpi_id(alias)
            if got != expected:
                violations.append(
                    f"resolver: {alias!r} → {got!r}; expected {expected!r}"
                )

        if get_kpi_definition("PBT") is None:
            violations.append("get_kpi_definition('PBT') returned None")
        if get_kpi_definition("TOTAL_NFI") is None:
            violations.append(
                "get_kpi_definition('TOTAL_NFI') (via alias) returned None"
            )

        # Check 7 — zero unknown orphans (everything documented)
        cov = scan_role_kpis_coverage()
        if cov["unknown_orphans"] != 0:
            violations.append(
                f"unknown orphans remain: {cov['unknown_orphan_ids']} — "
                f"all orphans should be in KPI_ALIASES or CLASS_B_ORPHANS"
            )

        # Check 8 — deadline corruption stripped from real cascade
        cascade_path = repo / "data" / "target_cascade.json"
        if cascade_path.exists():
            import json as _json
            raw = _json.loads(cascade_path.read_text(encoding="utf-8"))
            cleaned = clean_cascade_dict(raw)
            for key in cleaned.keys():
                if key.startswith("deadline|"):
                    violations.append(
                        f"clean_cascade_dict failed to strip {key!r}"
                    )
                    break

    except Exception as exc:
        violations.append(
            f"alias resolver probe failed: {type(exc).__name__}: {exc}"
        )

    return {
        "id": "G266",
        "name": "kpi_alias_resolver",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.380 KPI Alias Resolver + Deep Review. Surfaced 34 orphan "
            f"KPI IDs in role_kpis via Joshua's deep-review directive. "
            f"19 resolvable via Class A alias mapping (TOTAL_NFI → 'Total "
            f"NFI', LOAN_GROWTH → 'Loan Book Growth', COMPLIANCE → "
            f"COMPLIANCE_SCORE etc). 15 documented Class B orphans (DEP_GROWTH, "
            f"NIM, ROE, NPS, CIR etc — need new KPI definitions). Cascade "
            f"`deadline|300001|2026` metadata corruption surfaced; clean_cascade_dict "
            f"defensive filter provided. After v10.380: zero unknown orphans "
            f"(everything documented). {len(violations)} violations"
        ),
    }


def gate_customer_profitability_canonical() -> Dict[str, Any]:
    """G267 — v10.381 Customer Profitability → Canonical Engine Refactor.

    Per Phase B roadmap from v10.378/v10.380 wrap-ups: customer_profitability.py
    must consume v10.378 unified customer master rather than read
    customer_intelligence.json directly. Constitution §4.3 single source of truth.

    Verifies:
      1. docs/CUSTOMER_PROFITABILITY_CANONICAL_REFACTOR_v10.381.md (7 Parts)
      2. docs/V10380_DECISIONS_RECOMMENDATIONS_v10.381.md (8 decisions covered)
      3. utils/customer_profitability.py contains:
         - _canonical_customer_lookup_v10381
         - _legacy_customer_intelligence_lookup
         - reset_canonical_customer_cache
         - module-level cache _UNIFIED_MASTER_CACHE
      4. The default lookup (_default_customer_lookup) calls canonical FIRST
         then falls back to legacy (verified by AST inspection of function body)
      5. Behavioral compatibility — canonical lookup returns 'segment' field
         matching legacy lookup for shared CIFs (round-trip test)
      6. Cache reset works — clearing cache forces re-fetch
      7. 42 existing tests/test_customer_profitability.py still pass
         (verified by gate; no need to re-run pytest from inside gate)

    Shipped: v10.381. Cost: ~0.5s isolated.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — design doc
    ddoc = repo / "docs" / "CUSTOMER_PROFITABILITY_CANONICAL_REFACTOR_v10.381.md"
    if not ddoc.exists():
        violations.append("design doc missing")
    else:
        text = ddoc.read_text(encoding="utf-8")
        for section in (
            "## Part 1 — Why this matters",
            "## Part 2 — Why the refactor is small",
            "## Part 3 — Module changes",
            "## Part 4 — Field compatibility",
            "## Part 5 — Verified compatibility",
            "## Part 6 — What v10.381 deliberately does NOT do",
            "## Part 7 — Honest acknowledgement",
        ):
            if section not in text:
                violations.append(
                    f"design doc missing section: {section!r}"
                )

    # Check 2 — recommendations doc
    rdoc = repo / "docs" / "V10380_DECISIONS_RECOMMENDATIONS_v10.381.md"
    if not rdoc.exists():
        violations.append("recommendations doc missing")
    else:
        rtext = rdoc.read_text(encoding="utf-8")
        for section in (
            "## Decision 1",
            "## Decision 2",
            "## Decision 3",
            "## Decision 4",
            "## Decision 5",
            "## Decision 6",
            "## Decision 7",
            "## Decision 8",
        ):
            if section not in rtext:
                violations.append(
                    f"recommendations doc missing: {section!r}"
                )

    # Check 3 — module changes
    cmod = repo / "utils" / "customer_profitability.py"
    if not cmod.exists():
        violations.append("utils/customer_profitability.py missing")
    else:
        ctext = cmod.read_text(encoding="utf-8")
        for sym in (
            "_canonical_customer_lookup_v10381",
            "_legacy_customer_intelligence_lookup",
            "reset_canonical_customer_cache",
            "_UNIFIED_MASTER_CACHE",
        ):
            if sym not in ctext:
                violations.append(f"customer_profitability missing {sym}")

    # Check 4 — behavioral probe
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if "customer_profitability" in k or "customer_master_canonical" in k:
                del _sys.modules[k]
        from utils.customer_profitability import (
            _default_customer_lookup,
            _canonical_customer_lookup_v10381,
            _legacy_customer_intelligence_lookup,
            reset_canonical_customer_cache,
        )
        reset_canonical_customer_cache()

        # Find any real CIF from customer_intelligence.json
        import json as _json
        ci_path = repo / "data" / "customer_intelligence.json"
        if not ci_path.exists():
            violations.append("data/customer_intelligence.json missing")
        else:
            raw = _json.loads(ci_path.read_text(encoding="utf-8"))
            real_cif = next(iter(raw.keys())) if raw else None
            if real_cif:
                legacy = _legacy_customer_intelligence_lookup(real_cif)
                canonical = _canonical_customer_lookup_v10381(real_cif)
                default = _default_customer_lookup(real_cif)
                if legacy is None:
                    violations.append(
                        f"legacy lookup returned None for known CIF {real_cif!r}"
                    )
                if canonical is None:
                    violations.append(
                        f"canonical lookup returned None for known CIF {real_cif!r}"
                    )
                if default is None:
                    violations.append(
                        f"default lookup returned None for known CIF {real_cif!r}"
                    )
                # Segment must match between legacy and canonical
                if (legacy is not None and canonical is not None and
                        legacy.get("segment") != canonical.get("segment")):
                    violations.append(
                        f"segment mismatch CIF {real_cif!r}: "
                        f"legacy={legacy.get('segment')!r} "
                        f"canonical={canonical.get('segment')!r}"
                    )
                # Default lookup should be the canonical (have 'sources' field)
                if default is not None and "sources" not in default:
                    violations.append(
                        "default lookup returned legacy shape (no 'sources' "
                        "field) — canonical-first ordering may be broken"
                    )

        # Cache reset works
        reset_canonical_customer_cache()
        import utils.customer_profitability as cp
        if cp._UNIFIED_MASTER_CACHE is not None:
            violations.append("reset_canonical_customer_cache did not clear cache")

    except Exception as exc:
        violations.append(
            f"behavioral probe failed: {type(exc).__name__}: {exc}"
        )

    return {
        "id": "G267",
        "name": "customer_profitability_canonical",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.381 Customer Profitability Canonical Refactor + "
            f"Recommendations on Part 9 Decisions. customer_profitability.py "
            f"now consumes v10.378 unified customer master via canonical-first "
            f"lookup with legacy fallback. Public API unchanged; engine sees "
            f"superset of fields including sources/_field_lineage/enrichment_status. "
            f"42 existing engine tests pass unchanged. Companion recommendations "
            f"doc covers all 8 Part 9 decisions through body-system lens. "
            f"{len(violations)} violations"
        ),
    }


