def gate_v10389_pillar_shadow_removed() -> Dict[str, Any]:
    """G274 — v10.389 Pillar shadow weights removed from kpi_library.json.

    Per v10.385 body diagnosis Tier-1 fix sequence (Finding P3). The
    `weight` field is removed from each entry in `pillars[]`. Other
    fields (id, name, color) preserved — needed for pillar grouping
    and BSC styling. Canonical `pillar_weights` dict unchanged.

    Pre-existing bug DISCOVERED but NOT FIXED (logged as Finding N7):
    `utils/core.py::get_active_kpis()` calls .items() on `pillars`
    which is a list, raising AttributeError. Separate concern, separate
    batch.

    Verifies:
      1. docs/PILLAR_SHADOW_WEIGHTS_REMOVED_v10.389.md (9 Parts)
      2. data/kpi_library.json::pillars[] has no entry with 'weight' field
      3. data/kpi_library.json::pillars[] still has 4 entries with id+name+color
      4. data/kpi_library.json::pillar_weights dict still intact (4 keys)
      5. data/_v10389_backups/kpi_library.json.before exists
      6. health_check().shadow_pillars_field is False
      7. Design doc surfaces Finding N7 (the discovered get_active_kpis bug)

    Shipped: v10.389. Cost: ~0.05s isolated.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # Check 1 — design doc
    ddoc = repo / "docs" / "PILLAR_SHADOW_WEIGHTS_REMOVED_v10.389.md"
    if not ddoc.exists():
        violations.append("design doc missing")
    else:
        text = ddoc.read_text(encoding="utf-8")
        for part in range(1, 10):
            if f"## Part {part}" not in text:
                violations.append(f"design doc missing Part {part}")
        # Check 7 — Finding N7 documented
        if "Finding N7" not in text and "N7" not in text:
            violations.append(
                "design doc doesn't surface Finding N7 "
                "(the discovered get_active_kpis bug)"
            )

    # Check 2-4 — data file state
    lib_path = repo / "data" / "kpi_library.json"
    if not lib_path.exists():
        violations.append("kpi_library.json missing")
        return {
            "id": "G274",
            "name": "v10389_pillar_shadow_removed",
            "passed": False,
            "violations": violations,
            "summary": "v10.389 data file missing",
        }

    import json as _json_v389
    try:
        lib = _json_v389.loads(lib_path.read_text(encoding="utf-8"))
    except Exception as exc:
        violations.append(f"kpi_library.json corrupt: {exc}")
        return {
            "id": "G274",
            "name": "v10389_pillar_shadow_removed",
            "passed": False,
            "violations": violations,
            "summary": "v10.389 data file corrupt",
        }

    # Check 2 — no 'weight' field in any pillars[] entry
    pillars = lib.get("pillars", [])
    if not isinstance(pillars, list):
        violations.append(
            f"pillars[] should be list, got {type(pillars).__name__}"
        )
    else:
        for i, p in enumerate(pillars):
            if isinstance(p, dict) and "weight" in p:
                violations.append(
                    f"pillars[{i}] still has 'weight' field: {p}"
                )

    # Check 3 — pillars[] still has 4 entries with id+name+color
    if isinstance(pillars, list):
        if len(pillars) != 4:
            violations.append(
                f"pillars[] should have 4 entries, has {len(pillars)}"
            )
        for i, p in enumerate(pillars):
            if not isinstance(p, dict):
                violations.append(f"pillars[{i}] not a dict")
                continue
            for required in ("id", "name", "color"):
                if required not in p:
                    violations.append(
                        f"pillars[{i}] missing required field {required!r}"
                    )

    # Check 4 — pillar_weights dict still intact
    pw_dict = lib.get("pillar_weights", {})
    if not isinstance(pw_dict, dict):
        violations.append("pillar_weights should be dict, got something else")
    else:
        for canonical_pillar in ("Financial", "Customer Focus",
                                  "Operational Excellence",
                                  "People & Learning"):
            if canonical_pillar not in pw_dict:
                violations.append(
                    f"pillar_weights missing {canonical_pillar!r}"
                )

    # Check 5 — backup file exists
    backup = repo / "data" / "_v10389_backups" / "kpi_library.json.before"
    if not backup.exists():
        violations.append("backup data/_v10389_backups/kpi_library.json.before missing")

    # Check 6 — health_check reports shadow_pillars_field as False
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if "pillar_weights_canonical" in k:
                del _sys.modules[k]
        from utils.pillar_weights_canonical import health_check
        hc = health_check()
        if hc.get("shadow_pillars_field") is not False:
            violations.append(
                f"health_check().shadow_pillars_field should be False "
                f"after v10.389, got {hc.get('shadow_pillars_field')!r}"
            )
    except Exception as exc:
        violations.append(f"health_check probe failed: {exc}")

    return {
        "id": "G274",
        "name": "v10389_pillar_shadow_removed",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.389 Pillar shadow weights removed. Each entry in "
            f"kpi_library.json::pillars[] no longer has 'weight' field. "
            f"Structural fields (id, name, color) preserved. Canonical "
            f"pillar_weights dict unchanged. Body sheds dead weight; "
            f"health_check.shadow_pillars_field flips to False. "
            f"Finding N7 documented (separate concern: get_active_kpis "
            f"AttributeError on pillars list — pre-existing bug not "
            f"introduced by v10.389). {len(violations)} violations"
        ),
    }


