def gate_v10423_pillar_weights_decision() -> Dict[str, Any]:
    """G309 - v10.423 applies Kaplan-Norton 40/25/25/10 pillar weights.

    Per Joshua's decision: switch from bank-current 68/14/6/12 (Financial-
    heavy) to Kaplan-Norton balanced scorecard standard. Admin retains
    ability to vary via pages/7_admin.py -> KPI Library -> Pillar weights
    (already-built canonical UI at line 2111+ in admin module, with full
    validation and audit-trail history file).

    v10.423 changes:
      1. data/kpi_library.json::pillar_weights updated to:
         - Financial:              0.40
         - Customer Focus:         0.25
         - Operational Excellence: 0.25
         - People & Learning:      0.10
      2. Saved via existing utils.pillar_weights_canonical.save_pillar_weights
         (single source of truth - same path admin UI uses) so the change
         is recorded in pillar_weights_history.json with OLD/NEW values
         + actor + reason (audit traceability per §8.1)
      3. Admin can re-vary at any time via the existing canonical editor

    NO new engine module - admin editor was already built in v10.386.
    This batch ships ONLY: the data change + this gate + the decision
    documentation in CHANGELOG.

    Verifies:
      1. kpi_library.json::pillar_weights matches Kaplan-Norton 40/25/25/10
      2. All 4 pillars present (no dead organs)
      3. Sum = 1.0 within tolerance
      4. pillar_weights_history.json contains the v10.423 change record
      5. Admin canonical save path (utils.pillar_weights_canonical) still
         loadable and functional
      6. Engine state preserved 0/0/0/0

    Shipped: v10.423.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    expected = {
        "Financial": 0.40,
        "Customer Focus": 0.25,
        "Operational Excellence": 0.25,
        "People & Learning": 0.10,
    }
    tolerance = 0.001

    # Check 1-3: pillar_weights match
    import json as _json
    lib_path = repo / "data" / "kpi_library.json"
    if not lib_path.exists():
        violations.append("kpi_library.json missing")
    else:
        try:
            lib = _json.loads(lib_path.read_text(encoding="utf-8"))
            pw = lib.get("pillar_weights", {})
            for pillar, target in expected.items():
                actual = pw.get(pillar)
                if actual is None:
                    violations.append(f"pillar_weights missing: {pillar}")
                elif abs(float(actual) - target) > tolerance:
                    violations.append(
                        f"pillar_weights[{pillar}] = {actual}, expected {target}"
                    )
            total = sum(pw.values()) if pw else 0
            if abs(total - 1.0) > tolerance:
                violations.append(
                    f"pillar_weights sum = {total}, expected 1.0"
                )
        except Exception as exc:
            violations.append(f"pillar_weights parse failed: {exc}")

    # Check 4: history file has v10.423 record
    history_path = repo / "data" / "pillar_weights_history.json"
    if history_path.exists():
        try:
            history = _json.loads(history_path.read_text(encoding="utf-8"))
            entries = history if isinstance(history, list) else history.get("entries", [])
            has_v10423 = any(
                "v10.423" in str(e.get("reason", ""))
                or "kaplan" in str(e.get("reason", "")).lower()
                for e in entries
            )
            if not has_v10423:
                violations.append(
                    "pillar_weights_history.json missing v10.423 change record"
                )
        except Exception as exc:
            violations.append(f"history parse failed: {exc}")
    else:
        violations.append("pillar_weights_history.json missing")

    # Check 5: canonical save path module loadable
    try:
        import sys as _sys
        if str(repo) not in _sys.path:
            _sys.path.insert(0, str(repo))
        for k in list(_sys.modules):
            if "pillar_weights_canonical" in k:
                del _sys.modules[k]
        from utils.pillar_weights_canonical import (
            get_pillar_weights, save_pillar_weights, CANONICAL_PILLARS,
        )
        if set(CANONICAL_PILLARS) != set(expected.keys()):
            violations.append(
                f"CANONICAL_PILLARS mismatch: {CANONICAL_PILLARS}"
            )
    except Exception as exc:
        violations.append(f"pillar_weights_canonical import failed: {exc}")

    # Check 6: engine state
    try:
        for k in list(_sys.modules):
            if "cascade" in k and "buffer" not in k and "retain" not in k:
                del _sys.modules[k]
        from utils.cascade_structure_engine import full_audit
        s = full_audit().summary
        if s.get("rep_critical_count", -1) != 0:
            violations.append(
                f"rep_critical_count = {s.get('rep_critical_count')}"
            )
    except Exception as exc:
        violations.append(f"engine probe failed: {exc}")

    return {
        "id": "G309",
        "name": "v10423_pillar_weights_decision",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.423 applies Kaplan-Norton 40/25/25/10 pillar weights "
            f"(Financial 40%, Customer Focus 25%, Operational Excellence "
            f"25%, People & Learning 10%) per Joshua's decision. NO new "
            f"engine - admin editor in pages/7_admin.py:2111+ was already "
            f"built v10.386 with canonical save via utils.pillar_weights_"
            f"canonical (validation + audit-trail history). Admin can re-"
            f"vary at any time. The 40/25/25/10 split was canonical "
            f"Kaplan-Norton balanced scorecard standard; the previous "
            f"68/14/6/12 (Financial-heavy) reflected pre-2020 banking "
            f"defaults. Change recorded in pillar_weights_history.json "
            f"with full OLD/NEW + actor + reason audit trail. Engine "
            f"preserved 0/0/0/0. {len(violations)} violations"
        ),
    }



