        b1 = ev_b.evolve(base, days_elapsed=30.0)
        if abs(a1.cbk_central_bank_rate - b1.cbk_central_bank_rate) > 1e-9:
            violations.append("same seed → different CBR (not deterministic)")
        if abs(a1.usd_kes - b1.usd_kes) > 1e-6:
            violations.append("same seed → different USD/KES")

