        expected_t91 = base.treasury_91d + (0.085 - 0.10)
        if abs(shocked.treasury_91d - expected_t91) > 1e-6:
            violations.append(
                f"cbr_change broke t91 spread: {shocked.treasury_91d} "
                f"vs expected {expected_t91}"
            )

