def gate_v10495_react_foundations() -> Dict[str, Any]:
    """G381 - v10.495 React Foundations + Branding API.

    First React batch. Replaces the phantom G46 documented in
    frontend/web/README.md but never registered. G381 enforces
    the same architectural contract + the v10.495 amendment
    (BrandingProvider added between QueryClient and Auth).

    Per Joshua: "on the colors lets adopt the real eco bank blue"

    v10.495 wiring:
      - Backend: utils/config.py +4 helpers (brand_primary_hex,
        brand_secondary_hex, brand_accent_hex, ip_notice)
      - Backend: utils/api_branding.py NEW (GET /api/branding)
      - Backend: utils/api.py registers branding router (+2 lines)
      - Frontend: 16 files in frontend/web/ implementing the React
        SPA scaffolding with multi-tenant branding from API.

    G381 verifies on every audit run:
      1. utils/api_branding.py exists with router + get_branding()
      2. utils/config.py exposes the 4 new helpers
      3. frontend/web/src/App.tsx exists with original byte-for-byte
         contract literals preserved (the G46 README contract)
      4. App.tsx contains the BrandingProvider amendment
      5. frontend/web/src/providers/BrandingProvider.tsx exists
      6. frontend/web/src/main.tsx exists (Vite entry point)
      7. Brand colors set to Ecobank corporate defaults
      8. No hardcoded "Ecobank" string in frontend/web/src/**.tsx
         (the Dashboard.tsx, AuthProvider.tsx etc. must read from
         /api/branding via useBranding hook).

    Honest findings recorded:
      - G46 was phantom in scripts/audit.py — never registered
        despite being documented in frontend/web/README.md and
        frontend/web/mobile/README.md since April 29, 2026.
        G381 makes it real.
      - Deployed login uses navy gradient (#061422 -> #1a52a8);
        Ecobank corporate brand is cyan (#1797ce). v10.495 uses
        corporate brand per Joshua direction; visual divergence
        with Streamlit _login.py added to backlog as Track-C.
      - Original App.tsx (2,358 bytes) had no main.tsx companion
        — Vite needs both. v10.495 ships main.tsx as a missing-
        piece fix, not a contract change.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # 1. Backend files exist
    api_branding = repo / "utils" / "api_branding.py"
    if not api_branding.exists():
        violations.append("utils/api_branding.py missing")
    else:
        src = api_branding.read_text(encoding="utf-8")
        if "router = APIRouter" not in src:
            violations.append("utils/api_branding.py missing router")
        if 'def get_branding' not in src:
            violations.append("utils/api_branding.py missing get_branding()")
        if "/branding" not in src:
            violations.append("utils/api_branding.py missing /branding path")

    # 2. config.py exposes the 4 new helpers
    config_py = repo / "utils" / "config.py"
    if not config_py.exists():
        violations.append("utils/config.py missing")
    else:
        src = config_py.read_text(encoding="utf-8")
        for fn in ("brand_primary_hex", "brand_secondary_hex",
                    "brand_accent_hex", "ip_notice"):
            if f"def {fn}" not in src:
                violations.append(f"utils/config.py missing {fn}()")
        if "#1797ce" not in src:
            violations.append(
                "utils/config.py default brand_primary_hex not "
                "set to Ecobank corporate #1797ce"
            )

    # 3. frontend/web/src/App.tsx exists with contract literals
    app_tsx = repo / "frontend" / "web" / "src" / "App.tsx"
    if not app_tsx.exists():
        violations.append("frontend/web/src/App.tsx missing")
    else:
        src = app_tsx.read_text(encoding="utf-8")
        # Original G46 contract literals
        literals = [
            "import { QueryClient, QueryClientProvider } from '@tanstack/react-query'",
            "const queryClient = new QueryClient()",
            "<QueryClientProvider client={queryClient}>",
            "<AuthProvider><WebSocketProvider><BrowserRouter>",
            'path="/"',
            'path="/perform"',
            'path="/profitability"',
        ]
        for lit in literals:
            if lit not in src:
                violations.append(
                    f"App.tsx contract literal missing: {lit[:60]}"
                )
        # 4. BrandingProvider amendment
        if "BrandingProvider" not in src:
            violations.append(
                "App.tsx missing BrandingProvider amendment"
            )

    # 5. BrandingProvider exists
    bp_tsx = (repo / "frontend" / "web" / "src" / "providers"
                / "BrandingProvider.tsx")
    if not bp_tsx.exists():
        violations.append(
            "frontend/web/src/providers/BrandingProvider.tsx missing"
        )

    # 6. main.tsx exists
    main_tsx = repo / "frontend" / "web" / "src" / "main.tsx"
    if not main_tsx.exists():
        violations.append("frontend/web/src/main.tsx missing")

    # 8. No hardcoded "Ecobank" in .tsx source.
    #    Exception: BrandingProvider has fallback values.
    src_dir = repo / "frontend" / "web" / "src"
    if src_dir.exists():
        for tsx in src_dir.rglob("*.tsx"):
            if tsx.name == "BrandingProvider.tsx":
                continue  # fallback literals are allowed here
            if "Ecobank" in tsx.read_text(encoding="utf-8"):
                violations.append(
                    f"Hardcoded 'Ecobank' in {tsx.name} - use "
                    f"useBranding() instead"
                )

    return {
        "id": "G381",
        "name": "v10495_react_foundations",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.495 React Foundations + Branding API. "
            f"Replaces phantom G46. utils/config.py +4 helpers "
            f"(brand_primary_hex='#1797ce' Ecobank corporate, "
            f"brand_secondary_hex='#0e2440' deep navy, "
            f"brand_accent_hex='#ffd200' Ecobank yellow, ip_notice "
            f"with verbatim text from pages/_login.py:318). "
            f"utils/api_branding.py NEW exposing GET /api/branding. "
            f"utils/api.py registers branding router. Frontend: 16 "
            f"files implementing Vite+React+TS+Tailwind scaffolding "
            f"with BrandingProvider injecting tenant colors as CSS "
            f"variables. App.tsx amended: contract literals "
            f"preserved byte-for-byte, BrandingProvider added "
            f"between QueryClient and Auth providers. First "
            f"runnable React UI in A2Z history. {len(violations)} "
            f"violations"
        ),
    }



def gate_v10496_design_system() -> Dict[str, Any]:
    """G382 - v10.496 Design System brand discipline.

    First frontend design system batch. Builds 8 reusable component
    primitives (Button, Card, Input, Stat, Badge, Toast, Skeleton,
    Table) plus a Showcase / kitchen-sink page at /components.
    Dashboard.tsx refactored to use Stat + Card + Badge.

    G382 enforces "brand discipline" — the rule that the only React
    file allowed to contain non-brand semantic hex colors is
    `src/lib/tokens.ts`. Every other component reads:
      • brand colors via Tailwind `bg-brand-primary` etc. (which
        resolve via CSS vars set by BrandingProvider)
      • semantic colors via Tailwind semantic classes
        (`bg-red-50`, `text-amber-700`, etc.) — Tailwind's built-in
        palette is allowed because it's documented, accessible, and
        product-wide.

    What G382 verifies on every audit run:
      1. All 8 primitive files exist
      2. lib/cn.ts and lib/tokens.ts exist
      3. types/components.ts exists
      4. pages/Showcase.tsx exists
      5. Dashboard.tsx imports from @/components/* (proves refactor
         happened)
      6. App.tsx contains the /components route AND ToastProvider
      7. No file in src/components/** contains a hardcoded hex
         color (#xxxxxx pattern). Exception: brand css variables
         (`var(--brand-...)`) and tokens.ts itself.

    Honest finding recorded:
      - We deliberately did NOT install shadcn/ui CLI or Radix UI.
        v10.496 builds the design primitives by hand (~500 LOC,
        zero new deps) on the same visual API. If we ever need
        complex shadcn primitives (Dialog, Combobox, Popover with
        floating-ui positioning) we'll bring in the official CLI in
        a dedicated future batch. Until then, no new dependencies
        beyond what v10.495 shipped.
    """
    violations: List[str] = []
    repo = Path(__file__).parent.parent

    # 1. Primitive components all exist
    components_dir = repo / "frontend" / "web" / "src" / "components"
    required_components = [
        "Button.tsx", "Card.tsx", "Input.tsx", "Stat.tsx",
        "Badge.tsx", "Toast.tsx", "Skeleton.tsx", "Table.tsx",
    ]
    for name in required_components:
        if not (components_dir / name).exists():
            violations.append(
                f"frontend/web/src/components/{name} missing"
            )

    # 2. lib/cn.ts and lib/tokens.ts exist
    lib_dir = repo / "frontend" / "web" / "src" / "lib"
    for name in ("cn.ts", "tokens.ts"):
        if not (lib_dir / name).exists():
            violations.append(f"frontend/web/src/lib/{name} missing")

    # 3. types/components.ts
    types_file = (repo / "frontend" / "web" / "src" / "types"
                    / "components.ts")
    if not types_file.exists():
        violations.append(
            "frontend/web/src/types/components.ts missing"
        )

    # 4. Showcase page
    showcase = (repo / "frontend" / "web" / "src" / "pages"
                  / "Showcase.tsx")
    if not showcase.exists():
        violations.append(
            "frontend/web/src/pages/Showcase.tsx missing"
        )

    # 5. Dashboard.tsx imports from @/components
    dashboard = (repo / "frontend" / "web" / "src" / "pages"
                   / "Dashboard.tsx")
    if dashboard.exists():
        src = dashboard.read_text(encoding="utf-8")
        if "@/components/" not in src:
            violations.append(
                "Dashboard.tsx not refactored to use @/components/*"
            )

    # 6. App.tsx has /components route + ToastProvider
    app_tsx = repo / "frontend" / "web" / "src" / "App.tsx"
    if app_tsx.exists():
        src = app_tsx.read_text(encoding="utf-8")
        if 'path="/components"' not in src:
            violations.append(
                "App.tsx missing /components route"
            )
        if "ToastProvider" not in src:
            violations.append(
                "App.tsx missing ToastProvider"
            )

    # 7. No hardcoded hex colors in components/** except via
    #    var(--brand-*). Tokens.ts is allowed to have hex.
    import re
    hex_re = re.compile(r"#[0-9a-fA-F]{6}\b")
    if components_dir.exists():
        for tsx in components_dir.rglob("*.tsx"):
            text = tsx.read_text(encoding="utf-8")
            # Strip out everything inside `var(--...)` since those
            # are brand CSS vars set by BrandingProvider.
            stripped = re.sub(r"var\(--brand-[a-z]+\)", "", text)
            matches = hex_re.findall(stripped)
            if matches:
                violations.append(
                    f"Hardcoded hex color in components/{tsx.name}: "
                    f"{matches[:3]}"
                )

    return {
        "id": "G382",
        "name": "v10496_design_system",
        "passed": len(violations) == 0,
        "violations": violations,
        "summary": (
            f"v10.496 Design System. 8 primitive components "
            f"(Button, Card, Input, Stat, Badge, Toast, Skeleton, "
            f"Table) wired to /api/branding via Tailwind brand "
            f"tokens + CSS variables. Showcase page mounted at "
            f"/components. Dashboard.tsx refactored to compose "
            f"primitives. Zero new npm dependencies — built by "
            f"hand on the shadcn visual API. {len(violations)} "
            f"violations."
        ),
    }



