def run_all(only_gate: str | None = None) -> Dict[str, Any]:
    results = []
    for gid, fn in GATES:
        if only_gate and gid.lower() != only_gate.lower() and fn.__name__ != f"gate_{only_gate}":
            continue
        try:
            results.append(fn())
        except Exception as e:
            results.append({
                "id": gid, "name": fn.__name__.replace("gate_", ""),
                "passed": False, "summary": f"gate crashed: {e}",
                "violations": [str(e)],
            })
    passed = sum(1 for r in results if r["passed"])
    score_pct = (passed / len(results)) * 100 if results else 0
    return {
        "score_pct": round(score_pct, 1),
        "passed": passed,
        "total": len(results),
        "all_passed": passed == len(results),
        "gates": results,
    }


def render_human(report: Dict[str, Any]) -> str:
    lines = []
    lines.append("=" * 72)
    lines.append("A2Z MIS 360 — Automated Audit")
    lines.append("=" * 72)
    for r in report["gates"]:
        mark = "✅" if r["passed"] else "❌"
        lines.append(f"  {mark} [{r['id']}] {r['name']:<24} {r['summary']}")
        if not r["passed"] and r.get("violations"):
            for v in r["violations"][:8]:
                lines.append(f"        • {v}")
            if len(r["violations"]) > 8:
                lines.append(f"        … and {len(r['violations']) - 8} more")
    lines.append("-" * 72)
    lines.append(f"  Score: {report['passed']}/{report['total']} gates "
                 f"= {report['score_pct']}% — "
                 f"{'PASS' if report['all_passed'] else 'FAIL'}")
    lines.append("=" * 72)
    return "\n".join(lines)


def main() -> int:
    # Windows + non-UTF-8 console fix: the audit report contains UTF-8
    # characters (✅ ✗ ║ ═ — etc.) for human-readable rendering. On Windows
    # PowerShell with the default cp1252 / cp437 code page, print() raises
    # UnicodeEncodeError when these characters reach the console. Python
    # 3.7+ has a runtime opt-in to force UTF-8 on the stream regardless of
    # locale. Errors='replace' keeps print() never-crashing even if the
    # console truly cannot represent a glyph.
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            try:
                stream.reconfigure(encoding="utf-8", errors="replace")
            except Exception:
                # Old Python or non-reconfigurable stream — fall through;
                # worst case is the historical behaviour
                pass

    ap = argparse.ArgumentParser(description="A2Z automated audit")
    ap.add_argument("--json", action="store_true", help="machine-readable JSON output")
    ap.add_argument("--gate", type=str, default=None, help="run a single gate by id (g1, g2…)")
    args = ap.parse_args()

    report = run_all(only_gate=args.gate)

    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=False))
    else:
        print(render_human(report))

    return 0 if report["all_passed"] else 1


if __name__ == "__main__":
    sys.exit(main())
